/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
/* A12 checkpoint 1/4: first 20 frozen headwords. */
'use strict';
const D=globalThis.RA.D;
const q=(w,n,s,p,a,b,c,x)=>({id:`${w}.q${n}`,senseId:`${w}.s${s}`,errorType:'meaning',type:'辨义与用法',prompt:p,options:[a,b,c],answer:a,explain:x});
const m=(wrong,right,reason)=>({errorType:'meaning',wrong,right,reason});
const c=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const e=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:`Etymonline, https://www.etymonline.com/word/${encodeURIComponent(w.toLowerCase())}`});
D('cadence',{etymology:e('cadence 经法语 cadence、意大利语 cadenza 源自拉丁语 cadere“落下”；音乐中和弦进行的收束义与乐句“落定”相关。','cadence'),contexts:[c('cadence.s2','和声分析','The composer delayed the cadence by holding the dominant chord for two extra beats, making the audience wait for the phrase to resolve.','作曲家把属和弦多延长了两拍，推迟了终止式，让听众等待乐句收束。','The composer delayed the cadence / by holding the dominant chord for two extra beats / making the audience wait for the phrase to resolve.','delay 的宾语是 cadence；by 引出实现推迟的方式。','属和弦延宕后乐句才解决，指和弦终止式这一音乐义。')],mistakes:[m('The sentence had a steady cadence, with each spoken beat arriving in an uneven, unpredictable rhythm.','The sentence had an irregular cadence, with each spoken beat arriving in an uneven, unpredictable rhythm.','cadence 是节奏或韵律；若拍点不匀，steady 与描述矛盾。')],quiz:[q('cadence',1,1,'A speaker’s cadence is the pattern of?','rhythm and modulation in speech','spelling errors on a page','colors in a painting','cadence 可指说话的节奏和抑扬。'),q('cadence',2,2,'In tonal music, a cadence usually marks?','the close of a musical phrase','the tuning of a single instrument','the start of a recording session','音乐义 cadence 是乐句收束的和弦进行。'),q('cadence',3,1,'A slow, measured cadence describes someone’s?','rhythm of speaking or moving','exact height','choice of clothing','cadence 描述动作或言语节奏。'),q('cadence',4,2,'Which event is a musical cadence?','chords that bring a phrase to a close','a musician replacing a broken string','a drum being stored after rehearsal','和弦终止式使乐句收束。')]});
D('cadmium',{etymology:e('cadmium 于1817年由 Friedrich Stromeyer 发现并命名；词名来自拉丁语 cadmia（锌矿/炉渣名），最终关联希腊语 Kadmeia，古代底比斯附近的地名。','cadmium'),contexts:[c('cadmium.s1','电池回收','The recycling center kept the old nickel-cadmium cells in a sealed container because damaged batteries can release toxic cadmium compounds.','回收中心把旧镍镉电池放在密封容器里，因为损坏的电池可能释放有毒镉化合物。','The recycling center kept the old nickel-cadmium cells in a sealed container / because damaged batteries can release toxic cadmium compounds.','cadmium 修饰 compounds；because 引出密封存放的原因。','镍镉电池可能含有有毒镉，说明这是金属元素义。')],mistakes:[m('The lab labeled cadmium as a harmless gas that remains safe to breathe in any amount.','The lab labeled cadmium as a toxic metal that requires careful handling.','镉是有毒金属，不是可任意吸入的无害气体。')],quiz:[q('cadmium',1,1,'Cadmium is a?','bluish-white toxic metal','colorless noble gas','soft edible fruit','镉是有毒的蓝白色金属元素。'),q('cadmium',2,1,'Why are cadmium batteries handled as hazardous waste?','cadmium compounds can be toxic','cadmium is a kind of paper','they contain no metals','镉化合物有毒，需妥善回收。'),q('cadmium',3,1,'Which item may contain cadmium?','a nickel-cadmium rechargeable cell','a cotton towel with no dye','a wooden spoon','镍镉电池含有 cadmium。'),q('cadmium',4,1,'The chemical symbol for cadmium is?','Cd','Ca','Cm','镉的元素符号是 Cd。')]});
D('cajun',{etymology:e('Cajun 是 Louisiana French Acadien（Acadian）的英语拼写形式，指路易斯安那州阿卡迪亚移民后裔及其文化；Acadien 与 Acadia 的历史联系不应过度简化。','cajun'),contexts:[c('cajun.s2','路易斯安那饮食','At the festival, a Cajun band played fiddle and accordion while cooks served spicy rice dishes associated with the region’s French-influenced cuisine.','节庆上，一支卡津乐队演奏小提琴和手风琴，厨师则供应与该地区法国影响饮食相关的辣味米饭。','At the festival / a Cajun band played fiddle and accordion / while cooks served spicy rice dishes / associated with the region’s French-influenced cuisine.','Cajun 修饰 band，后文的 dishes 体现其文化关联。','乐队与地方菜肴呈现卡津文化义，对应 s2。')],mistakes:[m('The Cajun community in Louisiana traces its history to descendants of French Acadian settlers, but its food and music have no connection to Cajun culture.','The Cajun community in Louisiana traces its history to descendants of French Acadian settlers, whose food and music helped shape Cajun culture.','前半句已指卡津社群；断言其文化与卡津无关自相矛盾。')],quiz:[q('cajun',1,1,'A Cajun person is especially associated with which U.S. state?','Louisiana','Maine','Oregon','卡津社群主要与路易斯安那州相关。'),q('cajun',2,2,'Cajun music or food is?','related to the culture of Louisiana Cajun people','a language spoken only in Iceland','a style with no regional association','形容词义指卡津人的音乐、饮食等文化。'),q('cajun',3,1,'Cajun ancestry is historically connected with?','French Acadian settlers','Spanish settlers in the Philippines','Viking settlements in Alaska','Cajun 源于路易斯安那的阿卡迪亚后裔社群。'),q('cajun',4,2,'Which menu item could be described as Cajun?','a Louisiana-style seasoned rice dish','a plain label on a water bottle','a Swiss chocolate recipe by definition','路易斯安那风味菜可称 Cajun。')]});
D('calamitous',{etymology:e('calamitous 由 calamity 加形容词后缀 -ous 构成；calamity 经法语和拉丁语 calamitas 表示灾祸，词源更早部分有争议。','calamitous'),contexts:[c('calamitous.s1','灾害应对','The flood proved calamitous for the low-lying town: bridges collapsed, farms were ruined, and thousands of residents had to leave.','洪水给这座低洼城镇造成了灾难性后果：桥梁倒塌、农田被毁，数千居民不得不撤离。','The flood proved calamitous for the low-lying town / bridges collapsed / farms were ruined / and thousands of residents had to leave.','prove + 形容词表示结果证明如何；冒号后列举灾难后果。','重大损失和撤离说明洪水造成灾难。')],mistakes:[m('The harmless delay was calamitous because it caused no damage, loss, or serious consequence.','The harmless delay was minor because it caused no damage, loss, or serious consequence.','没有损失或严重后果的轻微延误不应称 calamitous。')],quiz:[q('calamitous',1,1,'A calamitous event has?','disastrous consequences','a mildly inconvenient effect','a guaranteed happy ending','calamitous 意为造成灾难的。'),q('calamitous',2,1,'Which outcome best fits a calamitous storm?','widespread destruction and loss','a few leaves moved on a quiet day','a forecast that changes by one degree','大范围破坏符合灾难性风暴。'),q('calamitous',3,1,'Calling a decision calamitous suggests it was?','disastrous in its results','carefully measured but harmless','ordinary and uneventful','此词强调结果灾难严重。'),q('calamitous',4,1,'Which is closest in meaning to calamitous?','catastrophic','beneficial','trivial','catastrophic 与造成灾难的意思相近。')]});
D('calcareous',{etymology:e('calcareous 经新拉丁语 calcareus 来自拉丁语 calx“石灰”，由此形成表示含有或由碳酸钙构成的形容词。','calcareous'),contexts:[c('calcareous.s1','土壤学','The botanist chose a calcareous soil rich in calcium carbonate because the wildflowers in the study plot thrive over limestone.','植物学家选择了富含碳酸钙的石灰质土壤，因为研究地块里的野花适宜生长在石灰岩上。','The botanist chose a calcareous soil rich in calcium carbonate / because the wildflowers in the study plot thrive over limestone.','calcareous 修饰 soil；because 引出选土的原因。','富含碳酸钙且与石灰岩环境相符，体现石灰质义。')],mistakes:[m('The geologist described the sample as calcareous because it contained no calcium carbonate and consisted entirely of pure quartz.','The geologist described the sample as siliceous because it contained no calcium carbonate and consisted largely of quartz.','calcareous 指含钙质/碳酸钙；纯石英样品不符合此义。')],quiz:[q('calcareous',1,1,'A calcareous rock contains substantial?','calcium carbonate','elemental gold','frozen water only','calcareous 指含碳酸钙的。'),q('calcareous',2,1,'Which landscape is likely to have calcareous soil?','land over limestone','a dune made entirely of clean quartz sand','a glacier with no underlying rock','石灰岩风化常形成钙质土壤。'),q('calcareous',3,1,'A botanist selecting calcareous ground is selecting soil that is?','lime-rich','completely free of calcium','made of pure metal','calcareous 的土壤含石灰质。'),q('calcareous',4,1,'Which word best contrasts with calcareous here?','siliceous','chalky','limestone-rich','siliceous 指富含硅质，与钙质相对。')]});
D('calcite',{etymology:e('calcite 是矿物学名，源于拉丁语 calx“石灰”；该名称由矿物学家 René Just Haüy 在18世纪末推广，用于主要成分为碳酸钙的矿物。','calcite'),contexts:[c('calcite.s1','矿物鉴定','The clear calcite crystal split light into two images of the printed line, a double refraction that helped the students identify the mineral.','透明方解石晶体把印刷线条折射成两个影像；这种双折射帮助学生辨认出该矿物。','The clear calcite crystal split light into two images of the printed line / a double refraction / that helped the students identify the mineral.','calcite 修饰 crystal；that 从句修饰 double refraction。','方解石的双折射是可观察的矿物性质，符合定义。')],mistakes:[m('The field guide identified calcite as a mineral made mainly of sodium chloride, the compound in table salt.','The field guide identified halite as a mineral made mainly of sodium chloride, the compound in table salt.','方解石是碳酸钙；食盐矿物氯化钠是 halite。')],quiz:[q('calcite',1,1,'Calcite consists mainly of?','calcium carbonate','sodium chloride','silicon dioxide only','方解石的主要成分是碳酸钙。'),q('calcite',2,1,'Which common rocks contain abundant calcite?','limestone and marble','coal and obsidian only','pure copper ore','石灰岩和大理岩主要含方解石。'),q('calcite',3,1,'A clear calcite crystal may demonstrate?','double refraction','radioactive decay in every sample','magnetic attraction to wood','方解石可产生双折射现象。'),q('calcite',4,1,'Calcite is the mineral form of which compound?','calcium carbonate','potassium nitrate','sodium bicarbonate','矿物 calcite 主要是碳酸钙。')]});
D('calculable',{etymology:e('calculable 由 calculate 加形容词后缀 -able 构成；calculate 源自拉丁语 calculare“用小石子计算”，与 calculus“小石子、算珠”同源。','calculable'),contexts:[c('calculable.s1','风险评估','Once the insurer had the bridge dimensions and the expected traffic volume, the likely repair cost became calculable rather than a guess.','保险公司掌握桥梁尺寸和预期车流量后，可能的维修费就可以计算出来，而不再只是猜测。','Once the insurer had the bridge dimensions and the expected traffic volume / the likely repair cost became calculable / rather than a guess.','calculable 作表语；once 引导条件/时间从句。','已有数据后维修成本可被计算，符合“可计算的”。')],mistakes:[m('The total was calculable, although no measurements or figures were available from which to estimate it.','The total was incalculable, because no measurements or figures were available from which to estimate it.','缺少任何数据、无法估算时用 incalculable，而非 calculable。')],quiz:[q('calculable',1,1,'A calculable quantity can be?','worked out or estimated with numbers','proved to be imaginary','described only by color','calculable 表示能够计算或估算。'),q('calculable',2,1,'What makes a repair bill calculable?','known prices and a measured amount of work','no prices and no information','a rumor about the building','已有价格和工程量才有依据计算费用。'),q('calculable',3,1,'Which pair are opposites in this context?','calculable and incalculable','calculable and numerical','calculable and measurable','incalculable 表示不可计算，与 calculable 相反。'),q('calculable',4,1,'The suffix -able in calculable contributes the sense?','capable of being calculated','the person who calculates','the past time of calculation','-able 表示“能够被……”。')]});
D('calculated',{etymology:e('calculated 是 calculate 的过去分词形容词；calculate 经法语源自拉丁语 calculare“用小石子计算”，形容词义由有意安排或计算得出发展而来。','calculated'),contexts:[c('calculated.s1','谈判策略','Her calculated pause before answering gave the negotiators time to reconsider their offer; it was a deliberate tactic, not hesitation.','她在回答前有意停顿，让谈判者有时间重新考虑报价；那是刻意策略，并非犹豫。','Her calculated pause before answering / gave the negotiators time to reconsider their offer / it was a deliberate tactic / not hesitation.','calculated 修饰 pause；冒号后说明停顿是有意安排。','刻意停顿以影响谈判结果，符合有意策划义 s1。')],mistakes:[m('The pilot made a calculated guess without checking any numbers, and meant the choice to be entirely accidental.','The pilot made an uncalculated guess without checking any numbers, and the choice was accidental.','刻意计算/策划的 calculated 与未经计算、偶然的决定相反。')],quiz:[q('calculated',1,1,'A calculated remark is usually?','deliberately chosen for an intended effect','spoken by accident with no thought','a result of measuring temperature','s1 指有意选择以产生某种效果。'),q('calculated',2,2,'A calculated total is one that has been?','worked out by arithmetic','chosen to manipulate an audience','guessed with no figures','s2 表示通过计算得出。'),q('calculated',3,1,'Which is a calculated move in a negotiation?','pausing deliberately to gain time','dropping a folder by accident','forgetting what was agreed','有意停顿以获得时间是策略安排。'),q('calculated',4,2,'If a value was calculated, it was?','determined using arithmetic','selected only for dramatic effect','never checked','此处 calculated 作“计算出来的”。')]});
D('calculating',{etymology:e('calculating 是 calculate 的现在分词形容词；由“计算、权衡”引申为冷静盘算个人利益，calculate 本身经拉丁语 calculare 与 calcul(us)“小石子”相关。','calculating'),contexts:[c('calculating.s1','人际关系','The calculating manager praised each colleague only when their support could help him secure the promotion he wanted.','这位精于算计的经理只在同事的支持有助于他获得晋升时才称赞他们。','The calculating manager praised each colleague only when their support could help him secure the promotion he wanted.','calculating 修饰 manager；only when 限定称赞的条件。','赞扬只服务于个人利益，体现冷静算计而不顾他人感受。')],mistakes:[m('She was calculating in the sense of being generous, spontaneous, and unconcerned with any personal advantage.','She was calculating in the sense of being strategic and focused on personal advantage.','精于算计强调为个人利益盘算，与慷慨随性相反。')],quiz:[q('calculating',1,1,'A calculating person tends to?','plan coldly for personal advantage','act generously without considering gain','avoid making any plans','calculating 描写冷静地盘算利益。'),q('calculating',2,1,'Which behavior seems calculating?','offering help only to obtain a favor later','helping anonymously with no reward expected','forgetting to make a schedule','帮助只为日后索取回报，体现算计。'),q('calculating',3,1,'The word calculating here carries what tone?','critical, suggesting self-interested planning','warmly admiring someone’s kindness','neutral praise for arithmetic skill only','形容人时常带批评色彩。'),q('calculating',4,1,'Which is closest in meaning to calculating (of a person)?','scheming','selfless','impulsive','scheming 同样指为私利盘算。')]});
D('calculator',{etymology:e('calculator 源自拉丁语 calculator“计算者”，由 calculare“计算”及施事者后缀 -tor 构成；现代电子计算器义随电子设备普及而形成。','calculator'),contexts:[c('calculator.s1','课堂数学','Before submitting her exam, Leila used a calculator to check the division and then wrote the result and working on the answer sheet.','交卷前，莱拉用计算器核对除法，然后把结果和步骤写在答题纸上。','Before submitting her exam / Leila used a calculator to check the division / and then wrote the result and working on the answer sheet.','calculator 是 used 的宾语；to check 表目的。','用于快速数学运算的电子小机器，对应 s1。')],mistakes:[m('The student entered 48 divided by 6 into the calculator, which is a person whose job is to estimate construction costs.','The student entered 48 divided by 6 into the calculator, the small electronic device used to do arithmetic.','按键输入的是电子计算器 s1；计算成本的工作人员是 s2 的人。')],quiz:[q('calculator',1,1,'A handheld calculator is a machine used to?','perform arithmetic quickly','print photographs on paper','measure a room’s temperature','电子计算器用于快速计算数学运算。'),q('calculator',2,2,'A professional calculator may be someone who?','works out figures such as costs','repairs only electronic screens','teaches people to drive','s2 也可指职业上的计算者。'),q('calculator',3,1,'Which object is a calculator in the common modern sense?','a pocket device with number keys','a ruler with no markings','a notebook of blank pages','常见义是带按键的电子计算器。'),q('calculator',4,1,'Which task best suits a calculator?','checking a division problem','boiling water','translating a poem aloud','计算器适合做除法运算。')]});
D('calculus',{etymology:e('calculus 是拉丁语“卵石、小石子”，古时小石子可用于计数；数学上的微积分义由此词在拉丁语中发展，医学义指体内形成的硬结石。','calculus'),contexts:[c('calculus.s2','医学检查','The scan showed a small calculus lodged in the kidney, and the physician discussed whether it could pass naturally or needed treatment.','扫描显示肾脏里嵌有一颗小结石，医生讨论它能否自然排出，还是需要治疗。','The scan showed a small calculus lodged in the kidney / and the physician discussed / whether it could pass naturally or needed treatment.','calculus 是 showed 的宾语；whether 引导间接疑问从句。','肾内形成的硬结石对应医学义 s2。')],mistakes:[m('The ultrasound found a calculus in the kidney, meaning a branch of advanced mathematics that studies rates of change.','The ultrasound found a calculus in the kidney, meaning a hard mass formed inside the body.','医学影像中的 calculus 指体内结石；微积分是数学学科义。')],quiz:[q('calculus',1,1,'In mathematics, calculus studies such ideas as?','rates of change','the spelling of ancient names','the classification of birds','微积分研究变化率等数学概念。'),q('calculus',2,2,'A kidney calculus is?','a hard mass formed inside the body','a mathematical lecture','a flexible blood vessel','医学义 calculus 指体内结石。'),q('calculus',3,1,'Which student is most likely taking calculus?','one studying derivatives and integrals','one learning only letter shapes','one practicing a musical scale','导数和积分属于微积分课程。'),q('calculus',4,2,'A doctor locating a calculus is likely looking for?','a stone-like deposit in an organ','a broken calculator','a change in a grammar rule','医生发现的 calculus 是结石。')]});
D('caliber',{etymology:e('caliber 经法语 calibre 进入英语；法语词通常追溯至阿拉伯语 qālib“模具”。英语保留枪管口径义，并引申为能力或品质的等级。','caliber'),contexts:[c('caliber.s2','人才评价','The research team recruited engineers of exceptional caliber, whose prior work showed both technical skill and sound judgment under pressure.','研究团队招募了才干出众的工程师；他们先前的工作体现出专业能力和压力下的良好判断力。','The research team recruited engineers of exceptional caliber / whose prior work showed both technical skill / and sound judgment under pressure.','of exceptional caliber 是后置品质描述；whose 从句修饰 engineers。','能力和判断力的高水平对应“才干、水准”义 s2。')],mistakes:[m('The report claimed that the caliber of the rifle measured the musical talent of its shooter instead of the barrel diameter.','The caliber of the rifle is the inside diameter of its barrel; caliber can also describe an individuals skill level.','枪械口径义和人的能力水准义相关但不同；原句混淆了指代对象。')],quiz:[q('caliber',1,1,'A person of high caliber has?','a high level of ability or quality','a large gun barrel','a low numerical temperature','人的 caliber 指能力或品质水平。'),q('caliber',2,1,'A rifle’s caliber refers to the?','inside diameter of its barrel or bullet','length of its wooden stock only','weight of the ammunition box','枪械 caliber 指枪管/子弹直径。'),q('caliber',3,2,'“A lawyer of her caliber” praises the lawyer’s?','ability and professional quality','height and physical build','choice of office furniture','此处 caliber 是才能与水准。'),q('caliber',4,1,'Which use refers to a firearm measurement?','the caliber of a pistol','the caliber of a pianist','the caliber of a research team','枪械 measurement 用 caliber 表示口径。')]});
D('calibrate',{etymology:e('calibrate 于19世纪由 caliber 加动词后缀 -ate 构成，先指确定枪炮口径，后扩展为调整仪器使测量正确。','calibrate'),contexts:[c('calibrate.s1','实验室测量','Before recording the samples, the technician calibrated the scale with certified weights so that each reading would be accurate.','记录样本前，技术员用标准砝码校准秤，确保每次读数准确。','Before recording the samples / the technician calibrated the scale with certified weights / so that each reading would be accurate.','calibrate 是及物动词，scale 为宾语；so that 引出目的。','用标准砝码调整秤的读数，使其准确，符合校准义。')],mistakes:[m('The lab calibrated the scale by deliberately leaving its zero point inaccurate and ignoring the certified weights.','The lab calibrated the scale by adjusting its zero point against the certified weights.','校准需依据标准调整仪器以获得准确读数，故意保持误差并非 calibrate。')],quiz:[q('calibrate',1,1,'To calibrate a scale is to?','adjust it so its readings are accurate','paint it a different color','remove all of its numbers','calibrate 是校准仪器读数。'),q('calibrate',2,1,'What should a technician use to calibrate a thermometer?','a reliable reference temperature','an unrelated household object','a handwritten guess','校准需与可靠参考值比较。'),q('calibrate',3,1,'Why calibrate a laboratory instrument?','to make its measurements dependable','to prevent it from displaying any result','to increase its weight','校准是为了保证测量准确可靠。'),q('calibrate',4,1,'Which action is calibration?','adjusting a meter against a known standard','covering the meter’s display','storing the meter without checking it','用已知标准调整仪表是校准。')]});
D('calibration',{etymology:e('calibration 由 calibrate 加名词后缀 -ion 构成；指为使仪器准确而检查调整的过程，也可指工具上用于读数的刻度。','calibration'),contexts:[c('calibration.s2','测量工具','The mechanic read the calibration on the caliper before measuring the metal rod, using the marked divisions to record its width.','技工测量金属杆前先读卡尺上的刻度，并用标出的分度记录宽度。','The mechanic read the calibration on the caliper / before measuring the metal rod / using the marked divisions to record its width.','calibration 作 caliper 上的刻度；using 短语说明读数方式。','卡尺上的标记分度对应刻度义 s2。')],mistakes:[m('The technician checked the calibration marks on the ruler, which were blank with no divisions or measurement labels.','The technician checked the ruler’s scale, which showed its divisions and measurement labels.','有读数刻度就不能同时是空白无刻度的尺；应改成有标记的 scale。')],quiz:[q('calibration',1,1,'Calibration of a scale is the process of?','checking and adjusting it for accurate readings','decorating it with a logo','replacing its batteries without testing it','calibration s1 是检查和调整以保持准确。'),q('calibration',2,2,'The calibration on a measuring tool can mean its?','marked scale or divisions','protective carrying case','manufacturer’s telephone number','s2 指工具上的刻度标记。'),q('calibration',3,1,'A sensor calibration usually compares readings with?','a known reference standard','an unrelated guess','the sensor’s paint color','已知参考标准有助于校准。'),q('calibration',4,2,'Which part shows a ruler’s calibration?','its measurement marks','its blank cardboard package','the table under it','尺上测量刻度对应 calibration 的刻度义。')]});
D('calibre',{etymology:e('calibre 与 caliber 是同一英语词的英式拼写；经法语 calibre 进入英语，通常追溯至阿拉伯语 qālib“模具”，有枪械口径及能力/品质等级义。','calibre'),contexts:[c('calibre.s2','人才评价','The orchestra needed a conductor of the highest calibre, someone able to shape the interpretation while earning the players’ trust.','乐团需要一位水准极高的指挥，既能塑造演绎，又能赢得乐手信任。','The orchestra needed a conductor of the highest calibre / someone able to shape the interpretation / while earning the players’ trust.','of the highest calibre 表示最高水准；someone 同位说明该人特质。','指挥才能和艺术品质的等级对应 s2。')],mistakes:[m('The rifle’s calibre is its barrel diameter, and this British spelling is an unrelated word meaning musical talent only.','The rifle’s calibre is its barrel diameter, and the word can also mean a person’s ability or quality.','calibre 与 caliber 是英美拼写变体，不是互不相关的词。')],quiz:[q('calibre',1,1,'A musician of high calibre has?','exceptional ability or quality','an unusually wide rifle barrel','a low reading on a thermometer','人才评价时 calibre 指才能水平。'),q('calibre',2,1,'In firearms, calibre measures the?','inside width of a barrel','number of bullets in a box','length of a rifle strap','枪械义指枪管内径。'),q('calibre',3,2,'Which statement about calibre is correct?','It is the British spelling of caliber.','It is a plural noun for musical notes.','It means only a tool for measuring temperature.','calibre 是 caliber 的英式拼写。'),q('calibre',4,2,'A “candidate of this calibre” means a candidate of this?','level of ability or quality','weight and height','brand of equipment','这里表示候选人的能力或水准。')]});
D('callous',{etymology:e('callous 经古法语 calleux 来自拉丁语 callosus“长硬皮的”，与 callum“硬皮、老茧”有关；由皮肤麻木引申出对他人痛苦冷漠。','callous'),contexts:[c('callous.s1','医疗伦理','The report criticized the callous decision to discharge a patient without arranging transport, even though staff knew he could not walk safely.','报告批评了冷酷的决定：工作人员明知患者无法安全行走，却让他出院且未安排交通。','The report criticized the callous decision to discharge a patient without arranging transport / even though staff knew he could not walk safely.','callous 修饰 decision；even though 引出与决定形成反差的已知事实。','明知患者面临危险仍漠视其处境，体现冷酷无情义 s1。')],mistakes:[m('The callous nurse showed deep concern for the patient’s pain and immediately arranged help.','The compassionate nurse showed deep concern for the patient’s pain and immediately arranged help.','关切并立即帮助患者是体恤，不是 callous 的冷漠。')],quiz:[q('callous',1,1,'A callous response to suffering shows?','a lack of care or sympathy','deep compassion','careful scientific measurement','callous s1 指对痛苦冷酷无情。'),q('callous',2,2,'Callous skin is skin that has become?','thick and hard from repeated friction','soft and newly healed','covered in fresh paint','皮肤义指因摩擦变厚变硬。'),q('callous',3,1,'Which action is callous?','ignoring an injured worker’s pleas for help','calling an ambulance immediately','offering a warm blanket','无视伤者求助体现冷漠。'),q('callous',4,2,'A callus on a hand is related to which meaning of callous?','hardened skin','insensitive behavior','a legal promise','callous 的皮肤义与老茧相关。')]});
D('calotype',{etymology:e('calotype 是 William Henry Fox Talbot 于1840年代为其纸底片摄影工艺所用的名称，借希腊语 kalos“美”与 typos“印记、类型”构成。','calotype'),contexts:[c('calotype.s1','摄影史','Unlike a direct positive process, the calotype produced a paper negative from which Talbot could make multiple positive prints.','与直接生成正像的工艺不同，卡罗式摄影会生成纸质底片，塔尔博特可据此制作多张正片。','Unlike a direct positive process / the calotype produced a paper negative / from which Talbot could make multiple positive prints.','calotype 作 produced 的主语；from which 引出底片的用途。','纸底片可反复印制正片，是卡罗式摄影工艺的特征。')],mistakes:[m('A calotype was a twentieth-century digital process that stored images on magnetic tape.','A calotype was a nineteenth-century photographic process that made paper negatives from which prints could be made.','卡罗式摄影是19世纪纸底片工艺，不是数字传感器。')],quiz:[q('calotype',1,1,'A calotype was an early photographic process associated with?','William Henry Fox Talbot','Louis Braille','Alexander Fleming','Talbot 发明并命名卡罗式摄影法。'),q('calotype',2,1,'What did a calotype process produce?','a paper negative','a digital image file','a glass lens without an image','卡罗式摄影生成纸底片。'),q('calotype',3,1,'Why was a paper negative useful?','it could be used to make multiple positive prints','it stored electricity for a camera','it prevented light from reaching the paper','底片可以用于制作多张正片。'),q('calotype',4,1,'Calotype belongs to the history of?','nineteenth-century photography','modern computer programming','ancient shipbuilding','calotype 是19世纪摄影术语。')]});
D('calumniate',{etymology:e('calumniate 源自拉丁语 calumniari“诬告、恶意指控”，与 calumnia“虚假指控”同源；进入英语后保留蓄意损害名誉的含义。','calumniate'),contexts:[c('calumniate.s1','新闻伦理','The editor refused to calumniate the scientist by publishing an accusation that the reporter knew was false and damaging.','编辑拒绝发表记者明知虚假且有害的指控来诽谤这位科学家。','The editor refused to calumniate the scientist / by publishing an accusation / that the reporter knew was false and damaging.','refuse to 后接动词原形；that 从句说明 accusation 的性质。','明知虚假仍发表有害指控属于恶意诽谤。')],mistakes:[m('The reviewer calumniated the historian by publishing an accurate, complimentary review of her book.','The reviewer praised the historian by publishing an accurate, complimentary review of her book.','calumniate 表示恶意诽谤；准确且赞美性的评论应使用 praised。')],quiz:[q('calumniate',1,1,'To calumniate someone is to?','make false damaging claims about them','give them a fair award','measure their height','calumniate 指恶意诽谤某人。'),q('calumniate',2,1,'Which act could calumniate a public figure?','knowingly spreading a false accusation','correcting a verified factual error','publishing a neutral weather report','故意散布虚假指控会损害名誉。'),q('calumniate',3,1,'Calumniate is closest in meaning to?','slander','commend','calculate','slander 是恶意诽谤的近义词。'),q('calumniate',4,1,'Which detail makes a statement calumnious?','it is false and intended to injure someone','it is accurate and complimentary','it is a question about arithmetic','虚假且意在伤人是诽谤关键。')]});
D('calumny',{etymology:e('calumny 来自拉丁语 calumnia“虚假指控、诬告”，经法语进入英语；词形与动词 calumniate 同源。','calumny'),contexts:[c('calumny.s1','公共言论','The candidate answered the calumny with documents showing that the alleged payments had never taken place.','候选人拿出文件回应诽谤，证明所谓的付款从未发生。','The candidate answered the calumny with documents / showing that the alleged payments had never taken place.','calumny 是 answered 的宾语；showing 分词短语说明文件内容。','所谓付款是虚假的有害指控，对应 calumny。')],mistakes:[m('The newspaper called the verified, accurate account of the public meeting a calumny even though it harmed no one and contained no false accusation.','The newspaper called the verified, accurate account of the public meeting a report even though it harmed no one and contained no false accusation.','经过核实的准确报道不是虚假诽谤；calumny 是假而有害的指控。')],quiz:[q('calumny',1,1,'A calumny is a?','false accusation intended to damage someone','verified report of a public event','method for calculating a total','calumny 指虚假且有损害性的指控。'),q('calumny',2,1,'Which response best answers a calumny?','evidence disproving the damaging false claim','an unrelated recipe','a second unsupported rumor','证据反驳虚假指控是合适回应。'),q('calumny',3,1,'Which word is a close synonym of calumny?','slander','compliment','calibration','slander 同样指诽谤。'),q('calumny',4,1,'A calumny differs from a truthful criticism because it is?','false and injurious','always spoken kindly','a mathematical calculation','虚假并有损害性是 calumny 的特点。')]});
D('calve',{etymology:e('calve 是由 calf（小牛）形成的古老英语动词，指母牛产犊；后来也用于冰川断裂并释放冰块，属于以“产出一块”作比喻的用法。','calve'),contexts:[c('calve.s2','冰川观测','The glacier began to calve into the fjord, sending a slab of ice crashing into the water as researchers watched from a safe ridge.','冰川开始向峡湾崩解，冰块轰然落入水中，研究人员在安全山脊上观察。','The glacier began to calve into the fjord / sending a slab of ice crashing into the water / as researchers watched from a safe ridge.','begin to 后接 calve；sending 分词结构表示伴随结果。','冰川断裂并释放冰块，对应 calve 的冰川义 s2。')],mistakes:[m('The glacier calved when it remained intact and released no ice into the sea.','The glacier advanced when it remained intact and released no ice into the sea.','calve 指冰川崩裂并脱落冰块；未崩解且无冰脱落时不成立。')],quiz:[q('calve',1,1,'When a cow calves, it?','gives birth to a calf','sheds its winter coat','learns to pull a plow','calve 的动物义是产小牛。'),q('calve',2,2,'When a glacier calves, it?','breaks off and releases a mass of ice','freezes all the ocean water','melts into rain without breaking','冰川 calve 指断裂并释放冰块。'),q('calve',3,1,'Which use of calve describes an animal?','The cow calved in the spring.','The glacier calved into the bay.','The ice shelf calved a berg.','母牛产犊句用 calve 的动物义。'),q('calve',4,2,'A large iceberg may form when a glacier?','calves and releases a piece of ice','calibrates its surface','grows grass on its edge','冰川脱落的大块冰可形成冰山。')]});
D('Cambridge',{etymology:e('Cambridge 的地名由 Cam 河名与古英语 brycg“桥”及集合/地名成分构成，原意是“Cam 河上的桥”；美国马萨诸塞州同名城市以英国剑桥命名。','Cambridge'),contexts:[c('Cambridge.s1','英国地理','During her term in Cambridge, Mei cycled beside the River Cam and attended lectures at the university’s old colleges.','梅在剑桥学习期间骑车经过剑河，并在大学的古老学院听课。','During her term in Cambridge / Mei cycled beside the River Cam / and attended lectures at the university’s old colleges.','Cambridge 作地点状语；并列动词 cycled 与 attended。','剑河与大学学院指向英格兰东部的剑桥城。')],mistakes:[m('Cambridge is the English city on the River Cam, so a visitor should expect it to be on the Pacific coast of California.','Cambridge is the English city on the River Cam, so a visitor should expect it in eastern England.','英格兰剑桥位于英格兰东部，不在加州太平洋海岸。')],quiz:[q('Cambridge',1,1,'The English city of Cambridge lies beside which river?','the Cam','the Danube','the Nile','英格兰剑桥位于剑河畔。'),q('Cambridge',2,1,'What is Cambridge especially famous for?','its historic university','a desert salt mine','a tropical coral reef','剑桥以大学闻名。'),q('Cambridge',3,1,'The name Cambridge originally refers to a bridge over the?','River Cam','River Thames at Oxford','Mississippi River','Cambridge 的地名与 Cam 河上的桥相关。'),q('Cambridge',4,1,'Which is also named Cambridge?','a city in Massachusetts','a mountain range in Peru','a sea in the Arctic','马萨诸塞州有一座同名城市。')]});
D('camcorder',{etymology:e('camcorder 是 camera 与 recorder 拼合成的缩略复合词，指把摄像与记录功能整合在一台便携设备中的摄录机。','camcorder'),contexts:[c('camcorder.s1','家庭影像','For the school play, Rina borrowed a camcorder that recorded video directly onto a memory card while she followed the actors from the aisle.','学校演出时，莉娜借了一台摄录机，在过道跟拍演员并将视频直接录到存储卡上。','For the school play / Rina borrowed a camcorder / that recorded video directly onto a memory card / while she followed the actors from the aisle.','camcorder 是 borrowed 的宾语；that 引导定语从句说明设备功能。','同一手持设备拍摄并录制视频，符合 camcorder 定义。')],mistakes:[m('A camcorder records moving pictures, but it has no camera and cannot capture any video.','A camcorder records moving pictures with a built-in video camera.','camcorder 本身整合摄像与录制功能，不能说没有相机且无法拍摄。')],quiz:[q('camcorder',1,1,'A camcorder combines a video camera with a?','recorder','projector','loudspeaker only','camcorder 是 camera 与 recorder 的合成词。'),q('camcorder',2,1,'Which task suits a camcorder?','recording a school performance as video','weighing a parcel','printing a paper map','摄录机用于拍摄并记录视频。'),q('camcorder',3,1,'A typical camcorder is designed to be?','portable and handheld','fixed permanently inside a wall','used only to play vinyl records','camcorder 通常是便携手持设备。'),q('camcorder',4,1,'Why is a camcorder different from a still camera?','it records moving video as well as capturing images','it cannot use a lens','it measures distance instead of recording','camcorder 的核心用途是摄录视频。')]});
D('cameral',{etymology:e('cameral 源自拉丁语 camera“房间、厅堂”，经近代欧洲语言用于议会或法庭的“议院/法庭”；单院制即 one chamber。','cameral'),contexts:[c('cameral.s1','宪政制度','The constitution established a cameral legislature with one elected chamber, so proposed laws did not pass through a second house.','宪法设立了单院制立法机关，只有一个民选议院，因此法案不必再经过第二院。','The constitution established a cameral legislature with one elected chamber / so proposed laws did not pass through a second house.','cameral 修饰 legislature；with 短语说明只有一个议院。','一个立法议院而无第二院，符合单院制的 cameral 义。')],mistakes:[m('The country’s cameral parliament had two separate legislative chambers that both had to approve each bill.','The country’s bicameral parliament had two separate legislative chambers that both had to approve each bill.','两个议院的制度是 bicameral；cameral 在词条中指单一议院。')],quiz:[q('cameral',1,1,'A cameral legislature has how many chambers in this entry’s sense?','one','two','none','cameral 指单一议院或法庭分庭。'),q('cameral',2,1,'Which adjective describes a parliament with one house?','cameral','bicameral','trilateral','单院立法机关可称 cameral。'),q('cameral',3,1,'The word cameral is used in relation to a chamber of?','a parliament or court','a household kitchen','a bicycle wheel','cameral 指议会或法庭的一个分庭。'),q('cameral',4,1,'A proposed law in a cameral legislature would be considered by?','a single chamber','two separate houses by definition','a jury of twelve only','单院制由一个议院审议。')]});
D('camouflage',{etymology:e('camouflage 经法语 camouflage 而来，法语动词 camoufler“伪装”可能受意大利方言 camuffare 影响；现代名词和动词义都与隐蔽有关。','camouflage'),contexts:[c('camouflage.s2','情绪表达','He tried to camouflage his disappointment with a joke, but his lowered voice made the real feeling obvious to his friends.','他试图用玩笑掩饰失望，但低落的声音让朋友们看出了真实情绪。','He tried to camouflage his disappointment with a joke / but his lowered voice made the real feeling obvious to his friends.','camouflage 是及物动词，宾语是 disappointment；with 表示掩饰手段。','玩笑被用来遮掩真实感受，对应抽象的掩饰义 s2。')],mistakes:[m('The soldiers used camouflage to make their uniforms stand out brightly against the forest.','The soldiers removed their camouflage so their uniforms would stand out against the forest.','伪装通常使人员融入背景、难以被发现，而非突出显眼。')],quiz:[q('camouflage',1,1,'To camouflage a feeling is to?','hide it behind a different appearance','make it easier for everyone to see','measure it with an instrument','动词 s2 指掩饰真实情绪或计划。'),q('camouflage',2,3,'Camouflage clothing helps soldiers by?','matching the surroundings to make them harder to see','making them shine in the dark','marking their exact position for the enemy','名词 camouflage 指融入环境的服装或材料。'),q('camouflage',3,1,'Which is an example of military camouflage?','netting colored to blend with nearby foliage','a bright flag mounted above a tent','a loud alarm attached to a uniform','伪装网利用环境颜色遮蔽装备。'),q('camouflage',4,2,'If someone camouflages a plan, the person?','conceals the true plan behind a false appearance','announces every detail openly','writes the plan in a notebook','抽象义是隐藏真实计划。')]});
D('campfire',{etymology:e('campfire 是 camp 与 fire 组成的透明复合词，早期指露营者在户外点燃、用于取暖或做饭的火。','campfire'),contexts:[c('campfire.s1','露营安全','After dusk, the group gathered around the campfire to cook supper, then poured water over the embers before leaving the campsite.','天黑后，大家围在营火旁做晚饭，离开营地前又把水浇在余烬上。','After dusk / the group gathered around the campfire to cook supper / then poured water over the embers / before leaving the campsite.','campfire 是 around 的宾语；before leaving 表示离开前。','营地户外生火做饭并在离开前熄灭，符合 campfire。')],mistakes:[m('The campers built a campfire inside their sealed nylon tent and left it burning while they slept.','The campers built a campfire in a cleared outdoor fire ring and extinguished it before sleeping.','篝火是在户外点燃的；在封闭帐篷内燃火会造成严重危险。')],quiz:[q('campfire',1,1,'A campfire is a fire lit?','outdoors where people are camping','inside a household refrigerator','underwater beside a ship','campfire 是露营时在户外点起的火。'),q('campfire',2,1,'What might campers do around a campfire?','cook food and sit together','measure a building’s height','repair a computer screen','营火可用于烹饪和露营聚集。'),q('campfire',3,1,'Before leaving a campsite, people should?','make sure the campfire is fully extinguished','add dry wood and walk away','hide the embers under a tent','离营前应彻底熄灭营火。'),q('campfire',4,1,'Which compound forms campfire?','camp plus fire','camera plus recorder','candle plus light','campfire 由 camp 和 fire 构成。')]});
D('Canadian',{etymology:e('Canadian 由 Canada 加形容词/居民后缀 -ian 构成，指属于加拿大、加拿大人民或其文化的；Canada 的词史另有争议。','Canadian'),contexts:[c('Canadian.s1','文化交流','The Canadian delegation brought maple products to the international fair and answered questions about life in several provinces.','加拿大代表团把枫树制品带到国际博览会，并回答了有关几个省生活的问题。','The Canadian delegation brought maple products to the international fair / and answered questions about life in several provinces.','Canadian 修饰 delegation；并列动词 brought 和 answered。','代表团来自加拿大并展示加拿大产品，体现形容词义。')],mistakes:[m('Toronto is a Canadian city, although it is located in France and governed by the French parliament.','Toronto is a Canadian city, located in Ontario and governed within Canada.','加拿大多伦多位于安大略省，并非法国城市。')],quiz:[q('Canadian',1,1,'Canadian describes something belonging to?','Canada or its people','Chile only','the Canary Islands only','Canadian 指加拿大及其人民。'),q('Canadian',2,1,'Which person is Canadian?','a citizen of Canada','a resident of Japan by nationality only','a visitor who has never been to Canada','Canadian 可作加拿大人的名词或形容词。'),q('Canadian',3,1,'Maple leaf imagery is often associated with?','Canadian identity','the Sahara Desert','the South Pole research station only','枫叶是加拿大常见国家象征。'),q('Canadian',4,1,'In “Canadian literature,” Canadian tells the reader the literature is related to?','Canada','a camera','a musical cadence','Canadian 作形容词表示与加拿大有关。')]});
D('canary',{etymology:e('canary 的“金丝雀”义经法语 canari 来自西班牙语 canario，原指加那利群岛；群岛名来自拉丁语 Canariae Insulae，早期解释或与犬有关。','canary'),contexts:[c('canary.s2','色彩搭配','The designer painted the child’s raincoat canary yellow so drivers could see it clearly on a gray morning.','设计师把孩子的雨衣刷成金丝雀黄，让司机在阴沉的早晨也能清楚看见。','The designer painted the child’s raincoat canary yellow / so drivers could see it clearly / on a gray morning.','canary 作颜色名词修饰 yellow；so 引出目的。','明亮的浅黄色来自金丝雀羽色的比喻，对应 s2。')],mistakes:[m('The canary-yellow warning vest was a deep, nearly black shade that drivers could not see.','The canary-yellow warning vest was a bright, light yellow shade that drivers could see.','canary yellow 是明亮的浅黄色，不是近乎黑色。')],quiz:[q('canary',1,1,'A canary is commonly kept for its?','small size and sweet song','ability to plow fields','thick wool coat','金丝雀是体型小、鸣声悦耳的鸟。'),q('canary',2,2,'Canary yellow is?','a light, bright yellow color','a dark violet shade','a type of blue-green fabric','颜色义指金丝雀羽毛般的明亮浅黄。'),q('canary',3,1,'The bird called a canary is historically associated with?','the Canary Islands','the Himalayas','the Great Lakes of North America','canary 的名称与加那利群岛相关。'),q('canary',4,2,'A canary-yellow sign would look?','bright yellow','nearly black','transparent and colorless','canary yellow 是鲜亮的黄。')]});
D('cancellation',{etymology:e('cancellation 由 cancel 加名词后缀 -ation 构成，cancel 经法语来自拉丁语 cancellare“划掉、作废”；可指取消安排或使票证失效。','cancellation'),contexts:[c('cancellation.s2','票务管理','The theater stamped the cancellation on the unused ticket, making it invalid for entry even though the performance itself went ahead.','剧院在未使用的票上盖了作废章，使它不能入场，尽管演出照常举行。','The theater stamped the cancellation on the unused ticket / making it invalid for entry / even though the performance itself went ahead.','cancellation 指作废标记/手续；even though 引出与票作废形成对照的演出情况。','演出继续但这张票被注销，体现证件作废义 s2。')],mistakes:[m('The concert’s cancellation meant that the scheduled performance would proceed at the original time with no change.','The concert’s cancellation meant that the scheduled performance would not take place.','取消演出意味着它不举行，而不是原定照常进行。')],quiz:[q('cancellation',1,1,'A cancellation of a meeting means the meeting?','will not take place as planned','has been extended by an hour','has already ended successfully','cancellation s1 指取消原定活动。'),q('cancellation',2,2,'The cancellation of a ticket can make it?','no longer valid','valid for every future event','larger in size','s2 指票证或合同作废。'),q('cancellation',3,1,'Which notice announces a cancellation?','“The match is called off.”','“The match begins on schedule.”','“The gates open early.”','called off 表明赛事取消。'),q('cancellation',4,2,'A stamp cancelling a document usually?','voids or invalidates it','renews it for another year automatically','translates it into another language','注销印章使文件失效。')]});
D('candid',{etymology:e('candid 经法语 candid(e) 来自拉丁语 candidus“白的、明亮的”；古罗马竞选者穿白袍的相关解释常见，但词义史不宜简单归结于此。','candid'),contexts:[c('candid.s2','新闻摄影','The photographer took a candid shot of the children laughing at the table, without asking them to turn toward the camera or pose.','摄影师抓拍了孩子们在桌边大笑的照片，没有要求他们看镜头或摆姿势。','The photographer took a candid shot of the children laughing at the table / without asking them to turn toward the camera or pose.','candid 修饰 shot；without 引出未摆拍的方式。','没有让被摄者摆姿势、自然拍到的照片对应 s2。')],mistakes:[m('The photographer described the formally posed portrait as candid because every subject was told exactly where to stand and when to smile.','The photographer described the formally posed portrait as staged because every subject was told exactly where to stand and when to smile.','被摄者按指示摆姿势的照片是摆拍，不是 candid 抓拍。')],quiz:[q('candid',1,1,'A candid answer is?','frank and honest, even about awkward facts','carefully hiding the speaker’s real view','a rehearsed musical performance','candid s1 指坦率直言。'),q('candid',2,2,'A candid photograph is usually taken?','informally without the subject posing','after everyone has arranged a formal pose','only from a written description','candid s2 指自然抓拍、非摆拍。'),q('candid',3,1,'Which comment is candid?','“The draft is unclear, and these two sections need revision.”','“Everything is perfect,” when the speaker knows it is not','a silent gesture with no meaning','坦诚指出问题是 candid 的表达。'),q('candid',4,2,'Which scene produces a candid shot?','a camera catches friends laughing naturally','the group lines up and follows pose instructions','the photographer draws a picture from memory','自然拍下的瞬间属于抓拍。')]});
D('candlelight',{etymology:e('candlelight 是 candle 与 light 的复合词，指燃烧蜡烛产生的光；该组合在英语中已有数百年用例。','candlelight'),contexts:[c('candlelight.s1','停电照明','During the outage, the family read by candlelight until the electrician restored power to the apartment.','停电期间，一家人借着烛光阅读，直到电工恢复公寓供电。','During the outage / the family read by candlelight / until the electrician restored power to the apartment.','by candlelight 表示照明方式；until 引导持续到何时。','蜡烛提供照明，符合 candlelight 的词义。')],mistakes:[m('They read by candlelight in a room where no candle was burning and no other source of light was present.','They read by candlelight in a room where a candle was burning.','没有燃烧的蜡烛就没有 candlelight。')],quiz:[q('candlelight',1,1,'Candlelight comes from?','one or more burning candles','a computer screen only','moonlight reflected from snow','candlelight 是蜡烛燃烧产生的光。'),q('candlelight',2,1,'To dine by candlelight is to dine?','with candles providing the light','in complete darkness','under a bright noon sun outdoors','by candlelight 表示以烛光照明。'),q('candlelight',3,1,'Which situation uses candlelight?','reading beside a lit candle during a power cut','reading beneath an electric streetlamp','reading in a room with no light at all','点燃的蜡烛可在停电时照明。'),q('candlelight',4,1,'The compound candlelight joins which ideas?','a candle and its light','a camera and a recorder','a camp and a fire','candlelight 由 candle 与 light 组合。')]});
D('cannibalism',{etymology:e('cannibalism 由 cannibal 加 -ism 构成；cannibal 经西班牙语 caníbal 与早期欧洲记载中的加勒比海地区族名相关，原始词源并不确定。','cannibalism'),contexts:[c('cannibalism.s1','动物行为','The biologist documented cannibalism among the newly hatched spiders, which sometimes ate smaller members of their own species when food was scarce.','生物学家记录了刚孵化的蜘蛛之间的同类相食：食物短缺时，它们有时会吃掉同种中更小的个体。','The biologist documented cannibalism among the newly hatched spiders / which sometimes ate smaller members of their own species / when food was scarce.','cannibalism 作 documented 的宾语；which 从句说明蜘蛛行为。','个体吃食同种个体，符合生物学定义。')],mistakes:[m('The zoologist called a lion eating a zebra cannibalism because both animals are members of the same species.','The zoologist called a lion eating a zebra predation because lions and zebras are different species.','狮子捕食斑马是异种捕食；cannibalism 要求同一物种成员相食。')],quiz:[q('cannibalism',1,1,'Cannibalism means eating an individual of?','one’s own species','a different species only','a plant species only','定义要求食用同种个体。'),q('cannibalism',2,1,'A spider eating a smaller spider of the same species is?','cannibalism','pollination','hibernation','同种蜘蛛相食属于 cannibalism。'),q('cannibalism',3,1,'Which scene is not cannibalism?','a wolf eating a rabbit','a fish eating a smaller fish of its own species','a human eating human flesh','狼和兔是不同物种，捕食不属同类相食。'),q('cannibalism',4,1,'The suffix -ism in cannibalism helps form a noun for?','a practice or behavior','a small person who calculates','a past-tense verb','-ism 可构成行为或实践的名词。')]});
D('cannonball',{etymology:e('cannonball 是 cannon 与 ball 的复合词，原指由大炮发射的实心球形弹丸；身体蜷成球状跃入水中的动作是形状相似的现代比喻义。','cannonball'),contexts:[c('cannonball.s2','游泳池活动','At the lake, Tomas made a cannonball by tucking his knees to his chest before splashing into the deep end.','在湖边，托马斯把膝盖抱到胸前，像炮弹式入水那样跳进深水区。','At the lake / Tomas made a cannonball / by tucking his knees to his chest / before splashing into the deep end.','make a cannonball 是入水动作；by 引出蜷身的姿势。','身体抱紧成球状入水，对应 s2。')],mistakes:[m('The museum displayed a cannonball that was a soft, hollow rubber beach toy fired harmlessly from a toy water pistol.','The museum displayed a cannonball, a solid round projectile once fired from a cannon.','历史 cannonball 是大炮发射的实心圆弹，不是软橡胶玩具。')],quiz:[q('cannonball',1,1,'A historical cannonball was usually?','a solid round projectile','a paper map of a battlefield','a wooden ship’s anchor','cannonball 的原义是实心球形炮弹。'),q('cannonball',2,2,'A swimmer does a cannonball by?','curling into a ball while jumping into water','lying flat on a diving board','walking slowly into shallow water','炮弹式入水时身体抱成球状。'),q('cannonball',3,1,'Which use refers to ammunition?','The cannonball struck the stone wall.','She made a cannonball into the pool.','The child drew a ball on paper.','击中石墙的 cannonball 是炮弹。'),q('cannonball',4,2,'The poolside cannonball is named for its?','round, tucked body shape','quiet entry with no splash','ability to float like a leaf','入水姿势因身体像圆球而得名。')]});
D('canny',{etymology:e('canny 是苏格兰语和英格兰北部英语中的形容词，可能由 can（知道、懂得）加 -y 构成，后来泛指精明、谨慎而会省钱。','canny'),contexts:[c('canny.s2','家庭理财','A canny shopper compared the unit prices and waited for a genuine discount instead of buying the largest package automatically.','精明的购物者比较了单位价格，并等到真正打折时再买，而不是自动选择最大包装。','A canny shopper compared the unit prices / and waited for a genuine discount / instead of buying the largest package automatically.','canny 修饰 shopper；instead of 后接动名词短语。','比较单价并谨慎消费，体现节俭审慎义 s2。')],mistakes:[m('The canny investor ignored all prices, bought whatever was riskiest, and never considered how to protect savings.','The reckless investor ignored all prices, bought whatever was riskiest, and never considered how to protect savings.','不顾价格与风险的投资行为是 reckless，不是精明谨慎的 canny。')],quiz:[q('canny',1,1,'A canny businessperson is especially good at?','judging business and making money','spending without checking the cost','avoiding every decision','canny s1 指善于判断生意并赚钱。'),q('canny',2,2,'A canny shopper is likely to be?','careful with money and risks','wasteful and impulsive','unable to compare prices','s2 强调谨慎和节俭。'),q('canny',3,1,'Which purchase is canny?','choosing a durable item after comparing prices','buying the first item at any price','borrowing money for a needless luxury','比较价格、重视价值体现精明。'),q('canny',4,1,'Canny often praises someone’s?','shrewd judgment','careless waste','physical strength','canny 常指判断精明。')]});
D('cantata',{etymology:e('cantata 是意大利语 cantata 的借词，字面与 cantare“歌唱”相关；17世纪形成的声乐器乐作品，区别于舞台化的歌剧。','cantata'),contexts:[c('cantata.s1','古典音乐','The choir and small orchestra performed a cantata whose soloists narrated a seasonal story without costumes or stage scenery.','合唱团和小型管弦乐队演出了一部康塔塔，独唱者讲述季节故事，但没有戏服或舞台布景。','The choir and small orchestra performed a cantata / whose soloists narrated a seasonal story / without costumes or stage scenery.','cantata 是 performed 的宾语；whose 从句说明作品由谁演唱。','声乐与器乐共同演出、非舞台歌剧，符合 cantata。')],mistakes:[m('The concert program listed a cantata as a silent sculpture made only for display in a museum.','The concert program listed a cantata as a vocal and instrumental musical composition.','cantata 是声乐器乐作品，不是静态雕塑。')],quiz:[q('cantata',1,1,'A cantata is written for?','singers and instruments','silent actors only','a solo dancer and no music','康塔塔为歌手和器乐写作。'),q('cantata',2,1,'Unlike an opera, a cantata is generally?','not staged as a dramatic opera','a purely visual painting','a type of musical instrument','词条定义指出通常不作歌剧式舞台呈现。'),q('cantata',3,1,'Which group might perform a cantata?','a choir with instrumentalists','a team of silent painters','a group of athletes','合唱团和器乐演奏者可共同演出康塔塔。'),q('cantata',4,1,'The word cantata is connected historically with the Italian verb meaning?','to sing','to carve','to calculate','意大利语 cantare 意为唱歌。')]});
D('canter',{etymology:e('canter 是 Canterbury gallop 的缩略形式，指较平稳、速度低于 gallop 的马步；其名与中世纪朝 Canterbury 朝圣者的行进步态有关。','canter'),contexts:[c('canter.s2','马术训练','After the warm-up, the rider asked the horse to canter around the arena, keeping a smooth rhythm between the slower trot and the gallop.','热身后，骑手让马在场地里慢跑，维持一种介于较慢的快步与疾驰之间的平稳节奏。','After the warm-up / the rider asked the horse to canter around the arena / keeping a smooth rhythm / between the slower trot and the gallop.','ask the horse to 后接动词原形；canter 是骑行动作义 s2。','骑手让马以 canter 步态前进，对应动词义。')],mistakes:[m('The horse cantered at the fastest full gallop, moving faster than any possible gallop.','The horse galloped at full speed, moving faster than it would at a canter.','canter 通常慢于 gallop；原句把两者速度关系倒置。')],quiz:[q('canter',1,1,'A horse’s canter is generally?','a smooth pace slower than a gallop','a motionless standing posture','faster than every possible gallop','canter 比 gallop 慢且平稳。'),q('canter',2,2,'If you canter a horse, you?','ride or move it at a canter','make it lie down permanently','measure its height with a ruler','canter 的动词义是以慢跑步态骑行或前进。'),q('canter',3,1,'Which sequence gives increasing horse speed?','walk, trot, canter, gallop','gallop, canter, trot, walk','canter, walk, gallop, trot','一般步态由慢到快如此排列。'),q('canter',4,2,'A rider asks a horse to canter around the arena. The word is used as a?','verb','color adjective','plural noun for saddles','此处 canter 是动词。')]});
D('cany',{etymology:e('cany 由 cane 加形容词后缀 -y 构成，表示长满芦苇/藤茎的，或外形像藤条的；此词较少见。','cany'),contexts:[c('cany.s1','植物描写','The cany marsh edge was tangled with tall reeds whose hollow stems bent over the narrow path.','沼泽边长满了藤茎般的高芦苇，空心茎秆弯垂在狭窄小路上。','The cany marsh edge was tangled with tall reeds / whose hollow stems bent over the narrow path.','cany 修饰 marsh edge；whose 引导定语从句修饰 reeds。','高芦苇覆盖的边缘符合“多藤茎/芦苇”的义项。')],mistakes:[m('The botanist called the field cany because it was completely bare, with no canes or reeds anywhere.','The botanist called the field open because it was completely bare, with no canes or reeds anywhere.','cany 描写多藤茎、芦苇或似藤条；寸草不生的地块不符合。')],quiz:[q('cany',1,1,'A cany area may be?','covered with canes or reeds','entirely bare of plant stems','made only of glass','cany 指多藤茎或芦苇。'),q('cany',2,1,'Which object could be described as cany in appearance?','a narrow, cane-like stem','a smooth sheet of ice','a round metal ball','形状像 cane 藤条也可称 cany。'),q('cany',3,1,'Which setting best fits a cany marsh edge?','tall reed stems crowd the bank','no plants grow anywhere on the bank','the bank is paved with concrete','芦苇密布的沼泽边缘是 cany。'),q('cany',4,1,'Cany is formed from cane plus a suffix meaning roughly?','having or characterized by','the act of measuring','without any connection to','-y 常构成“具有……特点的”形容词。')]});
D('capacious',{etymology:e('capacious 经拉丁语 capax“能容纳的”及 capac- 词干加 -ious 构成；可形容内部空间大，也可比喻心智或胸怀广阔。','capacious'),contexts:[c('capacious.s2','学习能力','Her capacious memory held the details of dozens of cases, yet she still listened carefully when a new student offered a different interpretation.','她记忆力极强，能记住数十个案例的细节；但新学生提出不同解释时，她仍会认真倾听。','Her capacious memory held the details of dozens of cases / yet she still listened carefully / when a new student offered a different interpretation.','capacious 修饰 memory；yet 连接转折内容。','能容纳大量知识的记忆体现比喻义 s2。')],mistakes:[m('The capacious suitcase held only one handkerchief because its interior was too tiny for any other item.','The cramped suitcase held only one handkerchief because its interior was too tiny for any other item.','内部狭小不能称 capacious；应改为 cramped。')],quiz:[q('capacious',1,1,'A capacious room has?','a large amount of interior space','no space to enter','a very low ceiling only','capacious s1 指内部宽敞、容量大。'),q('capacious',2,2,'A capacious mind can?','hold much knowledge or many ideas','remember absolutely nothing','fit only one short word','心智义表示能够容纳很多知识或想法。'),q('capacious',3,1,'Which object is likely capacious?','a large travel bag with room for many clothes','a tiny coin purse','a sealed empty envelope','容量很大的旅行包符合 capacious。'),q('capacious',4,2,'A capacious memory is best described as?','able to retain a great deal','easily emptied of all information','limited to a single fact','capacious 修饰记忆表示容量大。')]});
D('capillarity',{etymology:e('capillarity 由 capillary 与名词后缀 -ity 构成；capillary 源自拉丁语 capillaris“头发的”，指液体在狭细管隙中因表面张力等作用移动的现象。','capillarity'),contexts:[c('capillarity.s1','植物生理','Capillarity draws water through the narrow spaces in the soil, helping it move toward the fine roots even when gravity pulls downward.','毛细作用使水沿土壤的狭窄孔隙移动，即使重力向下拉，它也能向细根方向输送。','Capillarity draws water through the narrow spaces in the soil / helping it move toward the fine roots / even when gravity pulls downward.','capillarity 作主语；helping 分词短语说明其作用。','液体通过狭细孔隙移动是毛细现象。')],mistakes:[m('The water climbed a narrow glass tube by capillarity even though the tube’s inner surface repelled the liquid completely and no surface forces acted.','The water climbed a narrow glass tube by capillarity because surface forces acted in the narrow space.','毛细作用与狭小空间中的表面作用相关；若液体完全不润湿且无表面作用，不能这样解释。')],quiz:[q('capillarity',1,1,'Capillarity describes liquid movement through?','very narrow spaces or tubes','a wide open ocean only','a solid wall with no pores','capillarity 指狭细管隙中的液体移动。'),q('capillarity',2,1,'Which everyday effect illustrates capillarity?','water rising through a narrow wick','a stone falling under gravity','steam condensing on a broad ceiling only','灯芯中的液体上升是毛细现象的例子。'),q('capillarity',3,1,'Capillary action is strongly related to?','surface tension in small spaces','the speed of sound in air','magnetic poles in iron','毛细作用与表面张力等作用有关。'),q('capillarity',4,1,'The noun capillarity names a?','physical phenomenon','person who writes music','type of large ocean wave','capillarity 是物理现象名词。')]});
D('capillary',{etymology:e('capillary 经拉丁语 capillaris“头发的”来自 capillus“头发”；因毛细血管和毛细管极细而得名，可作名词或形容词。','capillary'),contexts:[c('capillary.s1','生理学','Oxygen passes from the blood into surrounding tissue through the walls of each tiny capillary, where the vessel is narrow enough for close exchange.','氧气通过每条微小毛细血管的管壁进入周围组织；血管足够细，便于近距离交换。','Oxygen passes from the blood into surrounding tissue through the walls of each tiny capillary / where the vessel is narrow enough for close exchange.','capillary 是介词 through 的宾语；where 从句说明交换的位置条件。','微小血管壁处进行气体交换，符合名词义 s1。')],mistakes:[m('The doctor identified the aorta as a capillary because it is the body’s largest artery carrying blood away from the heart.','The doctor identified the aorta as a major artery because it is the body’s largest artery carrying blood away from the heart.','毛细血管极细；主动脉是最大动脉，不能称 capillary。')],quiz:[q('capillary',1,1,'A blood capillary is?','a minute blood vessel','the largest artery in the body','a bone in the leg','capillary s1 指极细小的血管。'),q('capillary',2,2,'A capillary tube has a bore that is?','extremely narrow, like a hair','wide enough for a person to enter','solid with no opening','形容词义可指毛细管般细窄。'),q('capillary',3,1,'Where does exchange between blood and nearby tissue occur?','across capillary walls','inside the outer layer of a fingernail only','in the hair shaft','毛细血管壁是血液与组织交换的位置。'),q('capillary',4,2,'The adjective capillary in “capillary action” refers to something?','hair-thin or involving very narrow spaces','larger than a room','unrelated to narrow tubes','capillary 与极细结构及毛细作用有关。')]});
D('capitalism',{etymology:e('capitalism 由 capital 加 -ism 构成；capital 经法语源自拉丁语 capitalis“首要的”，资本意义逐渐发展，19世纪形成 capitalism 这一经济制度名称。','capitalism'),contexts:[c('capitalism.s1','经济制度','Under capitalism, private firms own factories and compete for profit, while laws determine how workers, consumers, and investors are protected.','在资本主义制度下，私人企业拥有工厂并为利润竞争，同时法律规定如何保护工人、消费者和投资者。','Under capitalism / private firms own factories and compete for profit / while laws determine / how workers, consumers, and investors are protected.','capitalism 作介词 under 的宾语；while 引出并行制度条件。','私人企业所有制及利润动机体现经济制度义 s1。')],mistakes:[m('Capitalism is an economic system based entirely on state ownership of every business and the abolition of private firms.','Socialism is an economic system often associated with public ownership, whereas capitalism permits private ownership of businesses.','把全面国有、取消私人企业说成 capitalism 与其私有经营核心相反。')],quiz:[q('capitalism',1,1,'Capitalism is an economic system in which businesses are commonly?','privately owned and operated for profit','all owned by the state by definition','run without any exchange or markets','资本主义以私人拥有企业并追求利润为特点。'),q('capitalism',2,2,'The plural sense capitalism can refer to?','countries using a capitalist economic system','individual calculators','all kinds of political speeches','词条也列出实行该制度的国家这一集合义。'),q('capitalism',3,1,'Which feature is associated with capitalism?','private firms compete to earn profits','private ownership is prohibited everywhere','money cannot be exchanged','私人企业竞争获利是常见特征。'),q('capitalism',4,1,'Which word names the system based on private business ownership?','capitalism','capillarity','candlelight','capitalism 是这种经济制度名词。')]});
D('capitalist',{etymology:e('capitalist 由 capital 加表示“支持者/从业者”的 -ist 构成；可指资本主义支持者，也可作形容词表示以私人资本经营为基础。','capitalist'),contexts:[c('capitalist.s2','经济思想','The capitalist argued that private entrepreneurs should be free to invest in new factories, while critics asked how workers would share in the gains.','这位资本主义支持者主张私人企业家应能自由投资建新工厂，而批评者则追问工人如何分享收益。','The capitalist argued that private entrepreneurs should be free to invest in new factories / while critics asked / how workers would share in the gains.','capitalist 是 argued 的主语；while 引出不同立场。','人物支持私人企业资本制度，对应名词义 s2。')],mistakes:[m('The capitalist supported private business ownership, but the term here means a person who opposes private enterprise.','The capitalist supported private business ownership, and the term here means a person who favors that system.','支持资本主义与反对私人企业相冲突；capitalist 此处指支持者。')],quiz:[q('capitalist',1,2,'A capitalist in the person sense is someone who?','supports an economy based on private business','rejects all private businesses','measures the width of a vessel','名词 s2 指资本主义支持者。'),q('capitalist',2,1,'A capitalist economy is characterized by?','private ownership of businesses for profit','the universal abolition of private ownership','no production or exchange','形容词 s3 指以私人所有和利润为基础。'),q('capitalist',3,1,'Which phrase uses capitalist as a noun?','a capitalist invested in the factory','a capitalist economy grew quickly','a capitalist system permits firms','“a capitalist” 指一个人。'),q('capitalist',4,3,'In “capitalist production,” capitalist is?','an adjective describing the economic system','a verb meaning to calculate','a noun for a tiny blood vessel','此处修饰 production，作形容词。')]});
D('capricious',{etymology:e('capricious 经法语 capricieux 和意大利语 capriccioso 与 capriccio 相关，表示突然而反复的心思或变化；更早词根解释有争议，不据流行说法断言。','capricious'),contexts:[c('capricious.s1','气候变化','The capricious spring weather shifted from warm sunshine to hail within an hour, forcing the gardeners to cover the new seedlings twice.','春天气候反复无常，一小时内从暖阳转成冰雹，园丁不得不两次给新苗加盖防护。','The capricious spring weather shifted from warm sunshine to hail within an hour / forcing the gardeners to cover the new seedlings twice.','capricious 修饰 weather；forcing 表示天气变化造成的结果。','天气无预警地快速变化，体现反复无常义。')],mistakes:[m('The capricious schedule remained fixed for a year and never changed despite every new circumstance.','The stable schedule remained fixed for a year and never changed despite every new circumstance.','始终不变的安排不是 capricious；该词指变化难以预测。')],quiz:[q('capricious',1,1,'A capricious decision-maker may?','change plans unpredictably','follow the same rule consistently','avoid making any decisions','capricious 指心思或决定反复无常。'),q('capricious',2,1,'Which weather is capricious?','sunshine changes suddenly to hail','steady rain continues all afternoon','a clear forecast matches the sky','天气突变符合 capricious。'),q('capricious',3,1,'The adjective usually suggests change that is?','unpredictable and without steady cause','carefully scheduled and consistent','mathematically certain','capricious 常含难以预料的变化。'),q('capricious',4,1,'Which is closest to capricious?','fickle','constant','reliable','fickle 表示反复无常。')]});
D('capriciousness',{etymology:e('capriciousness 由 capricious 加名词后缀 -ness 构成，表示情绪、方向或政策缺乏稳定原因而反复变化的性质。','capriciousness'),contexts:[c('capriciousness.s1','组织管理','Staff struggled with the director’s capriciousness because project priorities changed overnight without explanation or new evidence.','员工难以应对主管的反复无常，因为项目优先级在一夜间改变，却没有解释或新证据。','Staff struggled with the director’s capriciousness / because project priorities changed overnight / without explanation or new evidence.','capriciousness 是 struggled with 的宾语；because 引出困难原因。','缺乏理由地反复改变项目优先级，体现该名词义。')],mistakes:[m('The committee valued the policy’s capriciousness because its rules remained consistent and predictable in every case.','The committee valued the policy’s consistency because its rules remained consistent and predictable in every case.','稳定可预测的规则体现 consistency，而不是 capriciousness。')],quiz:[q('capriciousness',1,1,'Capriciousness is a tendency toward?','unpredictable changes of mood or direction','complete steadiness over time','careful measurement of length','capriciousness 指反复无常的倾向。'),q('capriciousness',2,1,'Why might workers object to a manager’s capriciousness?','priorities change without a clear reason','instructions stay stable and clear','the manager documents every decision','无端改变要求让员工无所适从。'),q('capriciousness',3,1,'Which quality contrasts with capriciousness?','consistency','fickleness','unpredictability','consistency 与反复无常相反。'),q('capriciousness',4,1,'The suffix -ness turns capricious into a noun for?','the state or quality of being capricious','a person who runs a factory','a past action','-ness 表示性质或状态。')]});
D('captious',{etymology:e('captious 经拉丁语 captiosus 来自 captio“诡辩、欺骗性的论点”，源自 capere“抓取”；英语中指爱抓小错、吹毛求疵。','captious'),contexts:[c('captious.s1','会议讨论','Instead of addressing the budget proposal, the captious reviewer objected to a minor comma and demanded that the whole report be rewritten.','吹毛求疵的评审没有讨论预算方案，而是挑出一个小逗号问题，要求重写整份报告。','Instead of addressing the budget proposal / the captious reviewer objected to a minor comma / and demanded that the whole report be rewritten.','captious 修饰 reviewer；instead of 引出其偏离主题的行为。','抓住无关紧要的小问题批评，符合挑剔义。')],mistakes:[m('The captious editor ignored every tiny flaw and praised the draft without making any criticism.','The approving editor ignored every tiny flaw and praised the draft without making any criticism.','不挑小错且赞扬文章的人不属于 captious。')],quiz:[q('captious',1,1,'A captious critic is eager to?','find fault with small points','praise every detail','avoid discussing any text','captious 表示爱挑小错。'),q('captious',2,1,'Which response is captious?','rejecting an argument over a tiny wording flaw','evaluating the main evidence fairly','thanking the speaker for a clear explanation','抓住小措辞瑕疵否定论点是吹毛求疵。'),q('captious',3,1,'Captious is closest in meaning to?','nitpicking','tolerant','carefree','nitpicking 指挑剔细枝末节。'),q('captious',4,1,'A captious objection often focuses on?','a trivial detail rather than the central issue','the main evidence and its importance','a well-supported conclusion only','captious 批评常抓小处。')]});
D('captivity',{etymology:e('captivity 经古法语 captivité 源自拉丁语 captivitas“被俘状态”，与 captivus“俘虏”同源；可指人被囚禁，也可指野生动物被圈养。','captivity'),contexts:[c('captivity.s2','野生动物保护','The sanctuary moved the injured eagle from captivity to a protected release program once veterinarians confirmed it could fly again.','兽医确认受伤的鹰可以重新飞行后，保护中心把它从圈养状态转入受保护的放归计划。','The sanctuary moved the injured eagle from captivity to a protected release program / once veterinarians confirmed it could fly again.','captivity 作介词 from 的宾语；once 引出转移时机。','野生动物在保护中心被圈养，对应 s2。')],mistakes:[m('The rescued tiger lived in captivity while roaming freely across its natural range with no enclosure or human care.','The rescued tiger lived in the wild while roaming freely across its natural range with no enclosure or human care.','在自然范围内自由活动是野生状态，不是 captivity 圈养。')],quiz:[q('captivity',1,1,'A person held in captivity is?','kept as a prisoner','free to leave whenever desired','working as a tour guide','captivity s1 指被囚禁状态。'),q('captivity',2,2,'A wild animal in captivity is?','kept in an enclosure or managed setting','living entirely free in its natural range','a fossil found in rock','动物义指被圈养。'),q('captivity',3,1,'Which change ends an animal’s captivity?','a successful release back into suitable habitat','moving it to a smaller cage','giving it a new enclosure name','放归合适栖息地可结束圈养状态。'),q('captivity',4,1,'Captivity is the opposite of?','freedom','confinement','imprisonment','freedom 与囚禁相反。')]});
D('caput',{etymology:e('caput 是拉丁语 caput“头”的借词；英语解剖学沿用它指器官或骨骼的头状端，复数形式 capita 也见于专业用语。','caput'),contexts:[c('caput.s1','解剖学','The anatomist identified the rounded caput of the femur, where the head of the thigh bone fits into the hip socket.','解剖学家辨认出股骨圆形的头端，即大腿骨头嵌入髋臼的部位。','The anatomist identified the rounded caput of the femur / where the head of the thigh bone fits into the hip socket.','caput 是 identified 的宾语；where 从句解释其解剖位置。','指骨骼的头状端，对应专业解剖义。')],mistakes:[m('The anatomist used caput to name the flat middle shaft of the femur, far from either head or end.','The anatomist used shaft to name the flat middle portion of the femur, far from either head or end.','caput 指头或头状端，不指长骨中段的 shaft。')],quiz:[q('caput',1,1,'In anatomy, caput can refer to?','the head or knob-like end of a structure','the middle shaft of every long bone','the skin covering the whole body','caput 指头状结构或骨端。'),q('caput',2,1,'The Latin source word caput means?','head','foot','water','caput 源自拉丁语“头”。'),q('caput',3,1,'A rounded end of a bone may be called its?','caput','cortex only','cartilage sheet','骨骼的头状端可称 caput。'),q('caput',4,1,'Which body part is least likely to be called a caput?','the central shaft of a long bone','a knob-like end of a bone','a head-shaped organ part','caput 强调头部或端部，而非骨干。')]});
D('carapace',{etymology:e('carapace 经法语 carapace 借入英语，指龟、甲壳类等动物背部的硬壳；更早的罗曼语词源存在不确定性。','carapace'),contexts:[c('carapace.s1','动物学观察','The turtle withdrew its legs beneath the carapace when the field team approached, leaving only the hard patterned shell visible.','野外小组靠近时，乌龟把腿缩进背甲下，只露出带花纹的硬壳。','The turtle withdrew its legs beneath the carapace / when the field team approached / leaving only the hard patterned shell visible.','carapace 作介词 beneath 的宾语；when 引出动作发生时机。','龟背部用于保护身体的硬壳即 carapace。')],mistakes:[m('The crab’s carapace was a soft, transparent membrane that offered no protection to its back.','The crab’s carapace was a hard shell that protected its back.','carapace 是坚硬的背甲，而不是柔软透明、毫无保护的膜。')],quiz:[q('carapace',1,1,'A turtle’s carapace is its?','hard protective shell','soft tongue','tail fin','carapace 指龟背甲。'),q('carapace',2,1,'Which animal has a carapace?','a crab','a sparrow','a salmon','甲壳类动物有 carapace。'),q('carapace',3,1,'What is the main function of a carapace?','protecting the animal’s back','helping it breathe underwater through gills','producing feathers','背甲提供保护。'),q('carapace',4,1,'A carapace is most accurately described as?','a hard outer shield','a soft internal organ','a movable eyelid','carapace 是硬质外部护甲。')]});
D('carat',{etymology:e('carat 经法语 carat 和意大利语 carato 来自阿拉伯语 qīrāṭ，最终与希腊语 keration“角豆荚/小角豆”有关；宝石质量单位与黄金纯度义须区分。','carat'),contexts:[c('carat.s1','珠宝称重','The jeweler weighed the diamond at two carats, meaning its mass was 400 milligrams rather than a measure of its gold purity.','珠宝商称这颗钻石重两克拉，即质量为400毫克，而不是黄金纯度的指标。','The jeweler weighed the diamond at two carats / meaning its mass was 400 milligrams / rather than a measure of its gold purity.','carat 作重量单位；meaning 补充说明两克拉对应质量。','一克拉等于200毫克，体现宝石质量义 s1。')],mistakes:[m('The ring’s diamond weighs 24 carats, which means the gold band is pure gold rather than giving the stone’s mass.','The ring’s gold is 24 carats, which indicates its purity rather than giving the diamond’s mass.','24 carat 描述黄金纯度；宝石质量的克拉数不是金纯度。')],quiz:[q('carat',1,1,'One carat of gemstone mass equals?','200 milligrams','one gram','24 milligrams','宝石质量单位一克拉为200毫克。'),q('carat',2,2,'Gold described as 24 carat is?','pure gold by this scale','a gemstone weighing 24 milligrams','gold mixed with exactly half copper','24克拉表示纯金。'),q('carat',3,1,'Which statement uses carat for a gemstone’s mass?','The diamond weighs three carats.','The bracelet is 18 carats gold.','The gold purity is 24 carats.','钻石三克拉使用质量义。'),q('carat',4,2,'Which use measures gold purity rather than stone weight?','an 18-carat gold ring','a 2-carat diamond','a 0.5-carat ruby','18克拉金戒指的 carat 指纯度。')]});
D('carbonate',{etymology:e('carbonate 由 carbon 与化学名词后缀 -ate 构成，可指含碳酸根的盐；作动词时指向饮料中溶入二氧化碳，或使物质转变为碳酸盐。','carbonate'),contexts:[c('carbonate.s2','饮料加工','The bottling line carbonates the water by dissolving carbon dioxide under pressure, then seals each bottle to retain the bubbles.','灌装线通过加压溶入二氧化碳使水碳酸化，随后密封每个瓶子以留住气泡。','The bottling line carbonates the water by dissolving carbon dioxide under pressure / then seals each bottle / to retain the bubbles.','carbonate 是及物动词；by 引出碳酸化方式。','加压将二氧化碳溶入水中，是动词义 s2。')],mistakes:[m('The laboratory called sodium carbonate a carbonate even though it contains no carbonate group and is only elemental gold.','The laboratory called sodium carbonate a carbonate because it contains the carbonate group.','碳酸钠含有碳酸根；若样品是单质金就不能称 carbonate。')],quiz:[q('carbonate',1,1,'A carbonate is a salt containing?','the carbonate group','only sodium metal','no carbon-containing group','名词 s1 指含碳酸根的盐。'),q('carbonate',2,2,'To carbonate water is to?','dissolve carbon dioxide in it','remove every gas from it','freeze it into solid ice','动词 s2 指把二氧化碳溶入饮料。'),q('carbonate',3,1,'Calcium carbonate is found in?','limestone and chalk','pure table sugar','elemental copper wire','石灰岩和白垩含碳酸钙。'),q('carbonate',4,2,'A fizzy drink is carbonated when?','carbon dioxide has been dissolved in it','all water has evaporated','it has been filtered through paper','溶入二氧化碳会使饮料起泡。')]});
D('carbonic',{etymology:e('carbonic 由 carbon 加形容词后缀 -ic 构成；carbon 一词经法语和拉丁语 carbo“煤、木炭”进入英语，carbonic 常用于碳酸或含碳相关化合物。','carbonic'),contexts:[c('carbonic.s1','化学实验','When carbon dioxide dissolves in water, a small amount forms carbonic acid, which contributes to the solution’s weak acidity.','二氧化碳溶于水时，少量会形成碳酸，使溶液呈现弱酸性。','When carbon dioxide dissolves in water / a small amount forms carbonic acid / which contributes to the solution’s weak acidity.','carbonic 修饰 acid；which 从句说明碳酸的影响。','carbonic acid 即二氧化碳溶于水形成的碳酸。')],mistakes:[m('Carbonic acid contains no carbon and is unrelated to carbon dioxide dissolved in water.','Carbonic acid contains carbon and can form when carbon dioxide dissolves in water.','碳酸含碳，其形成与二氧化碳溶于水有关。')],quiz:[q('carbonic',1,1,'Carbonic acid is related to which gas dissolved in water?','carbon dioxide','helium','neon','碳酸可由二氧化碳溶于水形成。'),q('carbonic',2,1,'The suffix -ic in carbonic forms?','an adjective','a plural noun','a past-tense verb','-ic 将 carbon 变为形容词。'),q('carbonic',3,1,'Which phrase uses carbonic correctly?','carbonic acid in a weak solution','carbonic spoon made of wood','carbonic means completely carbon-free','carbonic acid 是常见化学搭配。'),q('carbonic',4,1,'Carbonic is an adjective relating to?','carbon or carbonic acid','calcium-free muscle only','the heart’s electrical rhythm','carbonic 表示与碳或碳酸相关。')]});
D('carbonization',{etymology:e('carbonization 由 carbonize 加名词后缀 -ation 构成；carbonize 是 carbon 加 -ize，表示将木材或其他物质转化为富碳物质的过程。','carbonization'),contexts:[c('carbonization.s1','材料考古','The carbonization of the wooden seeds preserved their outlines in the ancient hearth, allowing archaeologists to identify the crops people had grown.','木种子经过碳化后在古火塘中保留了轮廓，使考古学家能辨认当时人们种植的作物。','The carbonization of the wooden seeds preserved their outlines in the ancient hearth / allowing archaeologists to identify the crops people had grown.','carbonization 是介词 of 的宾语；allowing 表示保存轮廓带来的结果。','木质材料转化为炭质并留下形状，符合碳化过程。')],mistakes:[m('Carbonization turned the wood into an unchanged, oxygen-rich fresh leaf without producing any carbon-rich residue.','Carbonization transformed the wood into a carbon-rich residue rather than an unchanged fresh leaf.','碳化会使物质转为富碳残留，不会让它保持新鲜叶片原状。')],quiz:[q('carbonization',1,1,'Carbonization is the conversion of material into?','carbon or carbon-rich residue','pure liquid water','a living green plant','carbonization 指转化为碳或富碳物质。'),q('carbonization',2,1,'What may preserve plant shapes in ancient charcoal?','carbonization','evaporation of all minerals','the growth of new leaves','碳化可保存植物原有轮廓。'),q('carbonization',3,1,'Which word is the base of carbonization?','carbonize','candid','capture','carbonization 来自动词 carbonize。'),q('carbonization',4,1,'The suffix -ation in carbonization marks?','a process or result noun','a person who studies plants','an adjective meaning blue','-ation 常构成过程或结果名词。')]});
D('carcase',{etymology:e('carcase 与 carcass 是同源拼写变体，经古法语/中古法语 carcasse 进入英语；早期词源解释不确定，现代可指动物屠体或建筑物的骨架。','carcase'),contexts:[c('carcase.s2','船舶检修','After the fire, inspectors examined the carcase of the fishing boat, checking whether its remaining frame could be salvaged.','火灾后，检查员查看渔船的骨架，判断剩下的船体框架能否抢修。','After the fire / inspectors examined the carcase of the fishing boat / checking whether its remaining frame could be salvaged.','carcase 作 examined 的宾语；checking 分词短语说明检查目的。','火后留下的船体骨架对应 s2。')],mistakes:[m('The carcase of a ship means its captain rather than its remaining frame.','The carcase of a ship means its remaining frame after damage.','carcase 指船只剩余骨架而非船长；应将误指船长改为船体残骸。')],quiz:[q('carcase',1,1,'A butcher may use carcase for?','the dead body of an animal prepared for meat','a living animal running in a field','a cooking pot','carcase s1 指动物尸体或屠体。'),q('carcase',2,2,'After a building burns, its carcase may be?','the remaining structural frame','a newly built roof','the fire inspector’s report','s2 指建筑物剩下的框架骨架。'),q('carcase',3,1,'Which spelling is a variant of carcase?','carcass','caring','carrot','carcass 是常见拼写变体。'),q('carcase',4,2,'The carcase of a wrecked vehicle is its?','remaining broken frame or shell','fresh paint color','fuel efficiency rating','车辆残骸可用 carcase 表示。')]});
D('carcass',{etymology:e('carcass 与英式 carcase 为同源拼写变体，经古法语/中古法语 carcasse 进入英语；可指死动物的躯体，也可比喻被毁物体剩下的外壳或骨架。','carcass'),contexts:[c('carcass.s2','灾后检查','Investigators photographed the burned carcass of the bus, whose twisted frame remained beside the road after the passengers had been evacuated.','乘客撤离后，调查人员拍下烧毁公交车的残骸；扭曲的车架仍留在路边。','Investigators photographed the burned carcass of the bus / whose twisted frame remained beside the road / after the passengers had been evacuated.','carcass 作 photographed 的宾语；whose 从句说明残骸状态。','车辆被毁后留下扭曲的骨架，符合 s2。')],mistakes:[m('The carcass of the wrecked bus was its brand-new replacement vehicle, not the broken shell left by the crash.','The carcass of the wrecked bus was the broken shell left by the crash.','未受损的新车不可能是 wreck 的残骸；用 intact bus 修正。')],quiz:[q('carcass',1,1,'A hunter may refer to a deer’s carcass as?','its dead body','its living herd','its antlers alone','carcass s1 指死动物的躯体。'),q('carcass',2,2,'The carcass of a destroyed car is?','the remaining wrecked shell or frame','a new spare tire','the driver’s license','s2 可指被毁汽车的残骸。'),q('carcass',3,1,'Which phrase uses carcass figuratively?','the carcass of a burned building','a carcass prepared by a butcher','a carcass of a dead animal','建筑烧毁后留下的骨架是比喻扩展义。'),q('carcass',4,1,'Carcass is closest in meaning to?','remains','blueprint','engineer','carcass 可指遗骸或残骸。')]});
D('carcinogenic',{etymology:e('carcinogenic 由 carcinogen 加形容词后缀 -ic 构成；carcinogen 结合希腊语 karkinos“癌”与 -gen“产生”，指可能导致癌症的因素。','carcinogenic'),contexts:[c('carcinogenic.s1','公共卫生','The warning label identified the chemical as carcinogenic, so workers wore protective equipment and followed strict exposure limits.','警示标签将这种化学品标为致癌物，工人因此穿戴防护装备并遵守严格的接触限值。','The warning label identified the chemical as carcinogenic / so workers wore protective equipment / and followed strict exposure limits.','carcinogenic 作宾语补足语说明 chemical；so 引出预防措施。','可能导致癌症的化学品需要控制接触，符合词义。')],mistakes:[m('The safety sheet called the substance carcinogenic because repeated exposure is proven to prevent cancer.','The safety sheet called the substance protective because repeated exposure is proven to prevent cancer.','能预防癌症与“可能致癌”相反，不应称为 carcinogenic。')],quiz:[q('carcinogenic',1,1,'A carcinogenic substance may?','cause cancer','cure every cancer','improve eyesight instantly','carcinogenic 指可能导致癌症。'),q('carcinogenic',2,1,'Why limit exposure to a carcinogenic chemical?','it may increase cancer risk','it is guaranteed to be harmless','it contains no active material','致癌物应限制接触以降低风险。'),q('carcinogenic',3,1,'Which warning best fits carcinogenic?','“May cause cancer; avoid inhaling vapors.”','“Safe to swallow in unlimited amounts.”','“Contains no chemical substance.”','可能致癌的物质需避免不当接触。'),q('carcinogenic',4,1,'The element carcin- in carcinogenic is associated with?','cancer','candle wax','a heart valve','carcin- 与癌症相关。')]});
D('cardiac',{etymology:e('cardiac 经拉丁语 cardiacus 源自希腊语 kardiakos“心脏的”，由 kardia“心”构成；医学上也可用作心脏病患者的名词。','cardiac'),contexts:[c('cardiac.s2','医院病房','The cardiac was transferred to a monitored ward after the emergency team stabilized his heart rhythm and reviewed his test results.','急救团队稳定了他的心律并查看检查结果后，这名心脏病患者被转入监护病房。','The cardiac was transferred to a monitored ward / after the emergency team stabilized his heart rhythm / and reviewed his test results.','cardiac 作患者名词；after 从句说明转病房之前发生的处置。','被转入监护病房且患心脏病的人对应 s2。')],mistakes:[m('The cardiologist referred to a healthy patient with no heart disease as a cardiac, meaning a person suffering from heart disease.','The cardiologist referred to the patient with heart disease as a cardiac, meaning a person suffering from heart disease.','若称某人为心脏病患者，需确有心脏疾病，不能指明确健康的人。')],quiz:[q('cardiac',1,1,'A cardiac test relates to the?','heart','kidneys only','skin and hair','形容词 s1 通常表示心脏的。'),q('cardiac',2,2,'In medical usage, a cardiac may be?','a patient suffering from heart disease','a person with no heart','a device that measures rainfall','cardiac 也可作心脏病患者名词。'),q('cardiac',3,1,'Which phrase uses cardiac as an adjective?','cardiac rhythm','a cardiac was admitted','two cardiac waiting','cardiac rhythm 中 cardiac 修饰名词。'),q('cardiac',4,2,'A doctor describing a patient as a cardiac is using the word as a?','noun','verb','preposition','患者义的 cardiac 作名词。')]});
D('cardiff',{etymology:e('Cardiff 的威尔士语名称为 Caerdydd，是威尔士首府专名；现代英语名经历史拼写发展而来，更早词素来源存在多种解释，故不强拆。','cardiff'),contexts:[c('cardiff.s1','威尔士地理','During their visit to Cardiff, the students walked along the waterfront on Cardiff Bay and later toured the Welsh national museum.','学生们访问加的夫时沿加的夫湾海滨散步，之后参观了威尔士国家博物馆。','During their visit to Cardiff / the students walked along the waterfront on Cardiff Bay / and later toured the Welsh national museum.','Cardiff 作地点状语；Cardiff Bay 是地名搭配。','加的夫湾和威尔士国家博物馆将地点定位在威尔士首府。')],mistakes:[m('Cardiff is the capital of Wales, a city in South America on the Pacific coast of Chile.','Cardiff is the capital of Wales, a city in the United Kingdom on the Bristol Channel.','加的夫是英国威尔士首府，位于布里斯托尔海峡沿岸，并非智利城市。')],quiz:[q('cardiff',1,1,'Cardiff is the capital of?','Wales','Scotland','Portugal','Cardiff 是威尔士首府。'),q('cardiff',2,1,'Cardiff lies on which body of water?','the Bristol Channel','the Mediterranean Sea','the Baltic Sea','加的夫位于布里斯托尔海峡附近。'),q('cardiff',3,1,'A person visiting Cardiff is in?','the United Kingdom','South America','New Zealand','Cardiff 位于英国威尔士。'),q('cardiff',4,1,'Which spelling is the Welsh name associated with Cardiff?','Caerdydd','Caerdydd is a river','Canterbury','威尔士语地名是 Caerdydd。')]});
D('cardiovascular',{etymology:e('cardiovascular 由希腊语 kardia“心”与拉丁语 vascularis（vasculum“小血管”）组合而成，形容与心脏和血管有关的结构或疾病。','cardiovascular'),contexts:[c('cardiovascular.s1','健康研究','The study linked regular exercise with better cardiovascular health, measuring both heart function and the condition of the blood vessels.','研究发现规律运动与较好的心血管健康有关，同时测量心脏功能和血管状况。','The study linked regular exercise with better cardiovascular health / measuring both heart function / and the condition of the blood vessels.','cardiovascular 修饰 health；both…and 并列心脏和血管两方面。','研究涵盖心脏与血管，因此 cardiovascular 用词准确。')],mistakes:[m('Cardiovascular disease affects only the skin and hair, with no involvement of the heart or blood vessels.','Dermatological disease affects the skin, while cardiovascular disease involves the heart or blood vessels.','心血管疾病涉及心脏或血管，不是仅影响皮肤和头发。')],quiz:[q('cardiovascular',1,1,'Cardiovascular relates to the heart and?','blood vessels','bones and joints','skin and nails','cardiovascular 由心脏和血管概念组成。'),q('cardiovascular',2,1,'Which condition is cardiovascular?','a disorder affecting arteries and the heart','a rash limited to the skin','a sprained ankle tendon','影响动脉和心脏的疾病属心血管疾病。'),q('cardiovascular',3,1,'Cardiovascular exercise is commonly intended to support?','heart and circulatory fitness','hearing and balance only','tooth enamel','该词与心血管系统健康有关。'),q('cardiovascular',4,1,'The word combines a form meaning heart with one related to?','vessels','feathers','stones','vascular 指血管相关。')]});
D('careerism',{etymology:e('careerism 由 career 加 -ism 构成，20世纪英语中指把个人职业晋升或成功置于忠诚、责任、理想之上的态度。','careerism'),contexts:[c('careerism.s1','职场伦理','Colleagues accused the executive of careerism when he abandoned the safety review to claim credit for a profitable launch.','高管为了抢占盈利发布的功劳而放弃安全审查，同事们因此指责他把个人升迁看得高于一切。','Colleagues accused the executive of careerism / when he abandoned the safety review / to claim credit for a profitable launch.','careerism 是 accused of 的宾语；when 从句提供被指责的行为。','为个人职业利益牺牲职责和安全审查，体现 careerism。')],mistakes:[m('Her careerism meant she rejected promotions and focused entirely on colleagues’ welfare rather than her own advancement.','Her selflessness meant she rejected promotions and focused entirely on colleagues’ welfare rather than her own advancement.','拒绝个人晋升并优先同事利益与 careerism 的自我晋升倾向相反。')],quiz:[q('careerism',1,1,'Careerism prioritizes?','professional advancement above duty or ideals','public service above personal gain','rest and recreation over work','careerism 指把职业成功置于责任或理想之上。'),q('careerism',2,1,'Which action suggests careerism?','taking credit for a project while ignoring its safety problems','sharing credit and reporting a genuine hazard','declining recognition to protect a team member','为晋升抢功并忽略安全是 careerism。'),q('careerism',3,1,'Careerism usually has what tone?','critical','purely medical','a term of praise for humility','该词通常带批评意味。'),q('careerism',4,1,'Which value contrasts with careerism?','loyalty to duty','self-promotion at any cost','personal advancement above all','将职责置于晋升之上与 careerism 相对。')]});
D('carefree',{etymology:e('carefree 是 care 与 free 组成的复合形容词，字面表示“没有忧虑”，用于轻松愉快且没有严重烦恼的状态。','carefree'),contexts:[c('carefree.s1','童年回忆','They spent a carefree afternoon building sandcastles, with no deadlines or worries pressing on them until sunset.','他们度过了一个无忧无虑的下午，堆沙堡直到日落，既没有截止任务也没有烦心事。','They spent a carefree afternoon building sandcastles / with no deadlines or worries pressing on them / until sunset.','carefree 修饰 afternoon；with 短语说明轻松的原因。','没有迫近的忧虑并轻松玩耍，符合 carefree。')],mistakes:[m('She felt carefree while worrying constantly about overdue rent, an exam tomorrow, and a serious family emergency.','She felt anxious while worrying constantly about overdue rent, an exam tomorrow, and a serious family emergency.','持续担心多件严重事情的状态是焦虑，不是 carefree。')],quiz:[q('carefree',1,1,'A carefree day is?','happy and free from serious worries','full of pressing problems','carefully planned as a legal contract','carefree 意为无忧无虑、轻松快乐。'),q('carefree',2,1,'Which person seems carefree?','someone relaxing without urgent concerns','someone panicking over several crises','someone awaiting an important verdict','没有迫切烦恼的人显得 carefree。'),q('carefree',3,1,'Which situation best fits a carefree holiday?','a relaxed trip with no pressing troubles','a trip spent handling a family emergency','a trip where every hour brings a new crisis','轻松且无重忧的假期符合 carefree。'),q('carefree',4,1,'The compound carefree joins care with free to suggest?','freedom from worry','being employed to provide care','careful attention to every detail','该复合词字面表示没有忧虑。')]});
D('carelessly',{etymology:e('carelessly 由 care 加 -less 构成 careless，再加副词后缀 -ly；表示做事未给予适当注意，常导致错误或损害。','carelessly'),contexts:[c('carelessly.s1','实验室安全','Marta carelessly left the chemical bottle uncapped beside the sink, so a coworker secured it before anyone was exposed.','玛尔塔粗心地把化学品瓶敞口放在水槽旁，同事赶在有人接触前把瓶子盖好。','Marta carelessly left the chemical bottle uncapped beside the sink / so a coworker secured it / before anyone was exposed.','carelessly 修饰 left，说明动作方式；so 引出补救结果。','未妥善盖好化学品且可能造成暴露，是粗心行为。')],mistakes:[m('He carelessly checked every figure twice, followed the safety checklist, and made no avoidable error.','He carefully checked every figure twice, followed the safety checklist, and made no avoidable error.','认真复核并遵循清单体现 carefully，而非 carelessly。')],quiz:[q('carelessly',1,1,'To act carelessly is to act?','without proper attention','with meticulous caution','only after a formal ceremony','carelessly 指缺少适当注意。'),q('carelessly',2,1,'Which action was done carelessly?','leaving a lab bottle open near a sink','labeling and sealing every chemical','checking a measurement twice','把实验瓶敞开放置是粗心行为。'),q('carelessly',3,1,'Carelessly writing a name may lead to?','an avoidable mistake','a guaranteed improvement in accuracy','a medical diagnosis','缺乏注意地书写可能导致错误。'),q('carelessly',4,1,'Which is the closest opposite of carelessly?','carefully','rashly','negligently','carefully 是 carelessly 的反义词。')]});
D('caribou',{etymology:e('caribou 经法语 caribou 来自米克马克语 qalipu 一类形式，指北美驯鹿；常见“以蹄刨雪”释义属于词源解释之一，细节仍有不确定性。','caribou'),contexts:[c('caribou.s1','北美生态','A herd of caribou crossed the tundra in early winter, pawing through the snow to reach the lichens beneath it.','初冬时，一群北美驯鹿穿过苔原，用蹄刨开积雪寻找下面的地衣。','A herd of caribou crossed the tundra in early winter / pawing through the snow / to reach the lichens beneath it.','caribou 是 herd of 后的复数动物名词；to reach 表目的。','北美苔原上的驯鹿刨雪觅食，符合该动物义。')],mistakes:[m('The field guide identified a caribou as a tropical parrot native to the Amazon rainforest.','The field guide identified a macaw as a tropical parrot native to the Amazon rainforest.','caribou 是北美驯鹿，不是热带鹦鹉。')],quiz:[q('caribou',1,1,'A caribou is a kind of?','reindeer native to northern North America','small tropical parrot','desert lizard','caribou 是北美原生驯鹿。'),q('caribou',2,1,'Where would a herd of caribou naturally range?','northern North American tundra','the Amazon rainforest','the Sahara dunes','北美北部苔原是驯鹿栖息地。'),q('caribou',3,1,'What might caribou paw through snow to find?','lichens and other food','coral reefs','salt water fish in a nest','它们会刨雪寻找地衣等食物。'),q('caribou',4,1,'Caribou is the usual North American term for a?','reindeer','camel','kangaroo','北美英语称这种驯鹿为 caribou。')]});
D('caricature',{etymology:e('caricature 经法语 caricature 来自意大利语 caricatura，源自动词 caricare“装载、夸张”；指通过放大特征来讽刺描绘，也可作动词。','caricature'),contexts:[c('caricature.s3','漫画讽刺','The cartoonist caricatured the mayor by enlarging his trademark mustache and tiny spectacles while exaggerating his habit of avoiding questions.','漫画家把市长标志性的小胡子和眼镜画得夸张，并夸大他回避问题的习惯来讽刺他。','The cartoonist caricatured the mayor / by enlarging his trademark mustache and tiny spectacles / while exaggerating his habit of avoiding questions.','caricatured 是及物动词，the mayor 为宾语；by 引出讽刺手法。','夸大外形特征和行为以进行嘲讽，符合动词义 s3。')],mistakes:[m('The artist caricatured the official by drawing a perfectly realistic portrait with no exaggeration or ridicule.','The artist portrayed the official in a realistic portrait with no exaggeration or ridicule.','不夸张、不讽刺的写实肖像不是 caricature。')],quiz:[q('caricature',1,1,'A caricature drawing typically?','exaggerates features to ridicule someone','copies every feature without distortion','records exact measurements for a passport','s1 指夸张特征以讽刺的画。'),q('caricature',2,2,'A written caricature of a leader is?','a mocking description that exaggerates faults','a neutral birth certificate','an exact list of election dates','书面 caricature 夸大缺点作讽刺描写。'),q('caricature',3,3,'To caricature a public figure is to?','depict them in an exaggerated mocking way','photograph them without posing','write a formal legal contract','动词义是夸张描绘以嘲讽。'),q('caricature',4,1,'Which technique creates a visual caricature?','enlarging a distinctive feature for comic effect','reproducing a face with no changes','measuring the frame width','夸张标志性特征可产生讽刺效果。')]});
D('carman',{etymology:e('carman 是 car 与施事者名词 man 的透明复合词；历史上可指驾驶运货车的人，较旧用法也指有轨电车司机。','carman'),contexts:[c('carman.s1','城市交通史','In the archive photograph, the carman guided a horse-drawn delivery cart through the market before motor lorries became common.','档案照片中，在机动车货车普及之前，运货车夫赶着马车穿过集市。','In the archive photograph / the carman guided a horse-drawn delivery cart through the market / before motor lorries became common.','carman 是 guided 的主语；before 引出更早的交通时代。','赶马拉货车的人对应历史职业义。')],mistakes:[m('The historian called the carman a passenger who sat in the cart and never drove or guided it.','The historian called the carman the driver who guided the delivery cart.','carman 指驾驶或赶车的人，不是乘坐货车的乘客。')],quiz:[q('carman',1,1,'Historically, a carman might drive a?','goods cart','passenger airplane','submarine','carman 可指驾驶运货车的人。'),q('carman',2,1,'In older usage, carman could also mean a?','tram driver','ship’s cook','court judge','旧用法还可指有轨电车司机。'),q('carman',3,1,'Which person best fits carman?','a worker steering a delivery cart','a shopper riding in the back','a mechanic who only repairs radios','驾驶/赶运货车的工人符合 carman。'),q('carman',4,1,'The compound carman joins car with?','man','candle','carnival','carman 是 car 与 man 的复合词。')]});
D('carnage',{etymology:e('carnage 经法语 carnage 源自表示“肉”的拉丁语 caro/carn- 词族，进入英语后指战争或袭击中大量残酷杀戮，也可比喻竞赛惨败。','carnage'),contexts:[c('carnage.s2','体育评论','The defending champions expected a close final, but a series of defensive errors turned the match into a 6–0 carnage.','卫冕冠军原以为决赛会势均力敌，但连续防守失误让比赛变成6比0的惨败。','The defending champions expected a close final / but a series of defensive errors turned the match into a 6–0 carnage.','carnage 作 turned … into 的补语；but 引出结果反转。','此处指竞赛中令人震惊的一边倒惨败，对应比喻义 s2。')],mistakes:[m('The match ended in carnage even though both teams tied at zero and neither side suffered a defeat.','The match ended in a deadlock even though both teams tied at zero and neither side suffered a defeat.','零比零平局没有任何一方惨败；这里应称为 deadlock。')],quiz:[q('carnage',1,1,'In its literal sense, carnage involves?','the cruel killing of many people','a small friendly gathering','a peaceful vote','carnage s1 指大量残酷杀戮。'),q('carnage',2,2,'In sports writing, carnage can mean?','a shocking, complete defeat','a narrow win by one point','a game cancelled before play','s2 是惨烈的一边倒败局。'),q('carnage',3,1,'Which situation best fits literal carnage?','a large number of people killed in an attack','a team winning a close match','a crowd leaving a theater','大量人员在袭击中被杀害符合本义。'),q('carnage',4,2,'A 10–0 defeat may be described figuratively as?','carnage','carnival','carnation','carnage 可比喻体育惨败。')]});
D('carnal',{etymology:e('carnal 经古法语 charnel 源自拉丁语 carnalis“肉体的”，来自 caro/carn-“肉”；英语中常与身体欲望、尤其性欲相对精神层面相对。','carnal'),contexts:[c('carnal.s1','文学评论','The novel contrasts the monk’s spiritual vows with his carnal desires, showing how bodily attraction complicates his promised devotion.','小说把修士的精神誓愿与肉体欲望对照，展现身体吸引力如何使其承诺的虔诚变复杂。','The novel contrasts the monk’s spiritual vows with his carnal desires / showing how bodily attraction complicates his promised devotion.','carnal 修饰 desires；with 构成对照的两项。','身体欲望与精神誓愿相对，体现 carnal 的词义。')],mistakes:[m('The essay used carnal to describe a purely spiritual devotion with no connection to bodily desire.','The essay used spiritual to describe a devotion with no connection to bodily desire.','纯精神、无身体欲望的奉献不能称 carnal。')],quiz:[q('carnal',1,1,'Carnal desires are related especially to?','bodily or sexual urges','abstract arithmetic','weather patterns','carnal 指肉体的、尤其肉欲的。'),q('carnal',2,1,'Which contrast commonly appears in writing?','carnal desire versus spiritual devotion','carnal geometry versus algebra','carnal rainfall versus snowfall','肉体欲望常与精神虔诚形成对照。'),q('carnal',3,1,'A carnal pleasure is primarily?','physical rather than spiritual','a legal document','a type of flower','carnal 强调身体层面。'),q('carnal',4,1,'The root carn- relates to?','flesh','light','water','carn- 与肉体相关。')]});
D('carnation',{etymology:e('carnation 经法语 carnation 与意大利语 carnagione 等词相关，原可指肉色或肤色；花名及其颜色义的发展关系复杂，不把单一路径说成定论。','carnation'),contexts:[c('carnation.s2','色彩设计','The textile designer chose a soft carnation shade for the lining, matching the pale pink fabric to the flower on the reference card.','纺织设计师为里衬选了柔和的康乃馨粉色，让浅粉面料与参考卡上的花朵相配。','The textile designer chose a soft carnation shade for the lining / matching the pale pink fabric / to the flower on the reference card.','carnation 修饰 shade；matching 分词表示配色效果。','颜色像康乃馨的淡粉或浅红，对应 s2。')],mistakes:[m('The designer called a deep black fabric carnation because its color matched the flower’s pale pink petals.','The designer called the fabric black because its color was deep black.','黑色面料不符合康乃馨花朵所对应的粉红色义。')],quiz:[q('carnation',1,1,'A carnation is a garden plant known for?','frilled flowers, often pink or white','spiny cactus pads','large yellow fruit','carnation s1 指康乃馨植物或花。'),q('carnation',2,2,'Carnation as a color is usually?','pink or light red','deep black','bright green','s2 指花朵般的粉红或浅红色。'),q('carnation',3,1,'Which item is a carnation?','a frilled pink flower in a bouquet','a hard mineral crystal','a winter reindeer','康乃馨是花卉。'),q('carnation',4,2,'A carnation-colored ribbon would most likely be?','soft pink','navy blue','charcoal gray','carnation 色是浅粉红色调。')]});
D('carnivore',{etymology:e('carnivore 由拉丁语 caro/carn-“肉”与 vorare“吞食”构成；可指食肉动物，也可幽默地称爱吃肉的人。','carnivore'),contexts:[c('carnivore.s2','餐桌闲谈','“I’m a carnivore,” Jules joked while choosing the steak, although he still ordered a salad and admitted that he occasionally ate vegetarian meals.','朱尔斯挑牛排时开玩笑说“我是个肉食爱好者”，不过他仍点了沙拉，也承认偶尔吃素。','“I’m a carnivore,” Jules joked while choosing the steak / although he still ordered a salad / and admitted that he occasionally ate vegetarian meals.','carnivore 作表语；引号及 joked 标明幽默自称。','此处将喜欢吃肉的人幽默称作 carnivore，对应 s2。')],mistakes:[m('The zoologist called a rabbit a carnivore because it eats only grass, leaves, and other plants.','The zoologist called a rabbit a herbivore because it eats only grass, leaves, and other plants.','只吃植物的兔子是食草动物，不是食肉动物。')],quiz:[q('carnivore',1,1,'A biological carnivore eats mainly?','meat from other animals','leaves and grass only','minerals and soil','carnivore s1 指以肉为食的动物。'),q('carnivore',2,2,'A person may jokingly call themself a carnivore if they?','love eating meat','never eat any food','prefer only raw vegetables','s2 可幽默指爱吃肉的人。'),q('carnivore',3,1,'Which animal is a carnivore?','a tiger that hunts prey','a cow eating grass','a mushroom growing on wood','捕食其他动物的虎是食肉动物。'),q('carnivore',4,2,'At dinner, “I’m a carnivore” most likely means?','I especially enjoy meat','I am a wild animal in a cage','I eat only fruit','日常玩笑中表示特别爱吃肉。')]});
D('carnivorous',{etymology:e('carnivorous 由拉丁语 carnivorus 构成，结合 caro/carn-“肉”与 vorare“吞食”；可指动物食肉，也指能捕捉并消化昆虫的植物。','carnivorous'),contexts:[c('carnivorous.s2','植物观察','The carnivorous sundew trapped small insects on its sticky leaf hairs and slowly digested them to supplement the poor nutrients in the bog.','食虫植物茅膏菜用叶面黏毛捕捉小昆虫，并慢慢消化，以补充沼泽土壤中不足的养分。','The carnivorous sundew trapped small insects on its sticky leaf hairs / and slowly digested them / to supplement the poor nutrients in the bog.','carnivorous 修饰 sundew；to supplement 表目的。','植物捕捉并消化昆虫，对应 carnivorous 的植物义 s2。')],mistakes:[m('The carnivorous plant trapped insects but never digested them or absorbed nutrients from its prey.','The insect-trapping plant caught insects but did not digest them.','若植物不消化昆虫，就不符合 carnivorous 植物义的定义。')],quiz:[q('carnivorous',1,1,'A carnivorous animal feeds on?','the flesh of other animals','sunlight alone','only mineral crystals','动物义指以其他动物的肉为食。'),q('carnivorous',2,2,'A carnivorous plant can?','catch and digest insects','produce fruit without any nutrients','run after its prey','植物义指捕捉并消化昆虫。'),q('carnivorous',3,2,'Which plant is carnivorous?','a sundew that digests trapped insects','an oak that makes acorns','a fern that absorbs water through roots only','茅膏菜捕虫消化，属于食虫植物。'),q('carnivorous',4,1,'Carnivorous contains a root meaning?','flesh or meat','candle','head','carniv- 与肉相关。')]});
D('carol',{etymology:e('carol 经古法语 carole 进入英语，早期可指圆圈舞及其歌曲；现代名词常指欢快赞歌、尤其圣诞颂歌，动词指唱颂歌。','carol'),contexts:[c('carol.s2','节庆合唱','Neighbors caroled outside the community hall after the winter concert, singing familiar songs while volunteers handed out warm drinks.','冬季音乐会后，邻居们在社区礼堂外欢唱颂歌，志愿者同时分发热饮。','Neighbors caroled outside the community hall after the winter concert / singing familiar songs / while volunteers handed out warm drinks.','caroled 是过去式动词；singing 补充说明演唱方式。','邻居们演唱节庆歌曲，对应动词义 s2。')],mistakes:[m('The choir caroled by remaining completely silent throughout the song and refusing to sing any lyrics.','The choir listened quietly while the soloist sang the carol.','沉默不唱歌不叫 carol；该动词指唱颂歌。')],quiz:[q('carol',1,1,'A Christmas carol is a?','song, often joyful or praising','type of winter coat','formal legal contract','名词 s1 常指圣诞颂歌。'),q('carol',2,2,'To carol is to?','sing carols or sing joyfully','carve a stone','ride a horse at a canter','动词 s2 指唱颂歌或欢唱。'),q('carol',3,1,'Which is a carol?','a group song sung at Christmas','a silent film without music','a list of train times','圣诞节群唱的歌曲是 carol。'),q('carol',4,2,'Neighbors caroled outside the hall. They?','sang together','built a stage','measured the roof','caroled 是“欢唱、唱颂歌”。')]});
D('carousel',{etymology:e('carousel 经法语 carrousel 进入英语，源自意大利语 carosello；先指骑马表演或竞技，后指游乐场旋转木马，也可指行李传送转盘。','carousel'),contexts:[c('carousel.s2','机场行李','At baggage claim, Theo waited beside carousel four until his suitcase circled past on the moving conveyor.','在行李提取处，西奥在四号行李转盘旁等着，直到他的手提箱随传送带转过来。','At baggage claim / Theo waited beside carousel four / until his suitcase circled past / on the moving conveyor.','carousel 是 beside 的宾语；until 引出等待结束时机。','机场循环移动的行李传送带对应 s2。')],mistakes:[m('At the airport, passengers collected bags from the carousel, which was a stationary shelf that never moved.','At the airport, passengers collected bags from the conveyor carousel, which moved bags around for collection.','行李 carousel 是循环移动的传送带，不是固定不动的架子。')],quiz:[q('carousel',1,1,'A fairground carousel is?','a circular ride with seats, often shaped like horses','a baggage claim desk','a stationary bookshelf','游乐场 carousel 是旋转木马。'),q('carousel',2,2,'At an airport, carousel refers to?','the circulating baggage conveyor','the passport itself','the plane’s cockpit','机场义指行李转盘。'),q('carousel',3,1,'Where would you wait for a suitcase at a carousel?','the baggage claim area','the cockpit during takeoff','a farm stable','行李提取处有传送转盘。'),q('carousel',4,1,'Which object goes round and round on a fairground carousel?','seats or horses','airplane wings','grocery shelves','旋转木马座椅绕中心转动。')]});
D('carpel',{etymology:e('carpel 是植物学术语，经新拉丁语 carpellum 源自希腊语 karpos“果实”；指花中承载胚珠、可构成雌蕊的叶状单元。','carpel'),contexts:[c('carpel.s1','植物解剖','Each carpel of the lily contained ovules inside its ovary, and the students traced how the separate parts joined to form the pistil.','百合每个心皮的子房内都有胚珠，学生们观察各个部分如何组合成雌蕊。','Each carpel of the lily contained ovules inside its ovary / and the students traced / how the separate parts joined to form the pistil.','carpel 是 contained 的主语；how 从句作 traced 的宾语。','承载胚珠且构成雌蕊的花部单元即心皮。')],mistakes:[m('The botanist labeled a petal as a carpel even though it bore no ovules and formed no part of the flower’s pistil.','The botanist labeled the ovule-bearing unit of the pistil a carpel.','不承载胚珠、也不属于雌蕊的花瓣不是 carpel。')],quiz:[q('carpel',1,1,'A carpel is a unit of a flower that bears?','ovules','stamens only','tree bark','心皮承载胚珠。'),q('carpel',2,1,'Carpels may join to form part of the?','pistil','root system','seed coat only','心皮可构成雌蕊。'),q('carpel',3,1,'Which feature identifies a carpel?','a leaf-like flower unit containing ovules','a leaf that absorbs sunlight outside the flower','a root hair','心皮是花内承载胚珠的叶状结构。'),q('carpel',4,1,'The Greek source karpos means?','fruit','head','fire','carpel 的词源与希腊语“果实”相关。')]});
D('carping',{etymology:e('carping 是动词 carp 的现在分词/形容词用法，指不断挑剔琐碎小错；carp 的更早词源解释不确定，不把“抓鱼”等同源猜测当定论。','carping'),contexts:[c('carping.s1','团队反馈','The reviewer’s carping comments about font size and punctuation obscured the report’s serious evidence about unsafe equipment.','评审不断挑剔字号和标点的评论，反而掩盖了报告中关于设备不安全的重要证据。','The reviewer’s carping comments about font size and punctuation / obscured the report’s serious evidence / about unsafe equipment.','carping 修饰 comments；about 引出挑剔的细节。','反复纠缠字号和标点等琐碎问题，符合 carping。')],mistakes:[m('The carping colleague offered one specific, useful correction and then praised every other part of the draft.','The supportive colleague offered one specific, useful correction and then praised every other part of the draft.','只提一条有用建议且整体赞扬，不是不断吹毛求疵。')],quiz:[q('carping',1,1,'A carping person repeatedly?','criticizes small, often trivial points','gives generous praise','avoids commenting on anything','carping 指持续挑剔琐事。'),q('carping',2,1,'Which comment is carping?','complaining repeatedly about tiny punctuation choices','noting a major factual error once','thanking the author for clear evidence','反复抱怨微小标点问题是 carping。'),q('carping',3,1,'Carping criticism usually focuses on?','petty details','the central evidence only','a celebration','carping 带有琐碎挑错意味。'),q('carping',4,1,'Which is closest to carping?','nitpicking','encouraging','celebrating','nitpicking 与 carping 意思相近。')]});
D('carrion',{etymology:e('carrion 经古法语 carogne 等形式进入英语，最终与拉丁语 caro/carn-“肉”词族相关；名词指腐烂动物尸肉，形容词指食腐或腐肉的。','carrion'),contexts:[c('carrion.s1','生态观察','Vultures circled above the carrion on the plain, while field researchers stayed back to avoid disturbing the scavengers.','秃鹫在平原上的腐肉上空盘旋，野外研究人员则退后，以免惊扰食腐动物。','Vultures circled above the carrion on the plain / while field researchers stayed back / to avoid disturbing the scavengers.','carrion 作 above 的宾语；while 对比秃鹫与研究人员的动作。','腐烂的动物尸肉是秃鹫的食物，对应名词义。')],mistakes:[m('The vulture fed on carrion freshly harvested from a healthy living plant.','The vulture fed on fruit freshly harvested from a healthy living plant.','carrion 是死动物的腐肉，植物上采摘的果实不是 carrion。')],quiz:[q('carrion',1,1,'Carrion is?','decaying flesh of dead animals','fresh vegetables from a garden','a live animal’s fur','carrion 指动物尸体腐肉。'),q('carrion',2,2,'A carrion bird feeds on?','dead animals','only living trees','stone minerals','形容词义指食腐的。'),q('carrion',3,1,'Which animal is a scavenger that may eat carrion?','a vulture','a hummingbird drinking nectar only','a rabbit eating grass','秃鹫常食腐肉。'),q('carrion',4,1,'A carrion smell would come from?','decaying animal remains','freshly baked bread','clean rainwater','腐烂动物遗骸会有 carrion 气味。')]});
D('cartilage',{etymology:e('cartilage 经古法语 cartilage 来自拉丁语 cartilago，指比骨柔韧的结缔组织；常见于关节、耳朵和鼻部。','cartilage'),contexts:[c('cartilage.s1','运动损伤','The scan revealed damaged cartilage in the player’s knee, so the physician recommended rest before he returned to high-impact training.','影像显示球员膝部软骨受损，因此医生建议他恢复高强度训练前先休息。','The scan revealed damaged cartilage in the player’s knee / so the physician recommended rest / before he returned to high-impact training.','cartilage 作 revealed 的宾语；so 引出检查结果后的建议。','关节内柔韧组织受损，体现软骨义。')],mistakes:[m('The doctor described cartilage as a rigid metal plate that is harder than bone and found only in the knee.','The doctor described cartilage as tough, flexible tissue softer than bone, found in joints and other body parts.','软骨比骨柔韧且较软，也见于耳鼻等处，不是金属板。')],quiz:[q('cartilage',1,1,'Cartilage is tissue that is generally?','tough and flexible, but softer than bone','a rigid metal implant by definition','a liquid found only in the stomach','软骨坚韧有弹性，通常比骨头软。'),q('cartilage',2,1,'Where can cartilage be found?','joints, ears, and the nose','only in the hair','inside a fingernail only','软骨存在于关节、耳、鼻等处。'),q('cartilage',3,1,'What may be damaged in a knee injury?','cartilage','a carpel','a canary feather','膝关节损伤可能涉及软骨。'),q('cartilage',4,1,'Cartilage differs from bone because it is usually?','more flexible and less rigid','made of wood','an external shell','软骨比骨骼柔韧。')]});
D('carver',{etymology:e('carver 由 carve 加施事者后缀 -er 构成，可指雕刻木石或象牙的人；在餐桌语境中也可指用来切熟肉的大刀。','carver'),contexts:[c('carver.s2','厨房餐具','At the holiday dinner, Elena handed her father the carver so he could slice the roast into even portions for the guests.','节日晚餐时，埃琳娜把切肉刀递给父亲，让他把烤肉均匀切成几份给客人。','At the holiday dinner / Elena handed her father the carver / so he could slice the roast into even portions for the guests.','carver 是 handed 的宾语；so 引出递刀目的。','用来切熟肉的大刀对应 carver 的 s2。')],mistakes:[m('The host passed the carver to the guest as a spoon for stirring tea and eating soup.','The host passed the carver to the guest as a large knife for slicing roast meat.','切肉刀不是用于搅茶或喝汤的勺子。')],quiz:[q('carver',1,1,'A wood carver is a person who?','shapes wood by cutting','drives a delivery cart','studies heart disease','carver s1 指雕刻工。'),q('carver',2,2,'At dinner, a carver is a?','large knife for cutting cooked meat','small spoon for sugar','glass used to serve water','s2 是餐桌切肉大刀。'),q('carver',3,1,'Which person is a carver in the craft sense?','an artist cutting a figure from stone','a guest eating at a table','a driver waiting for a bus','雕刻石头的人符合 carver 的职业义。'),q('carver',4,2,'Which task uses a table carver?','slicing a roast for dinner','stirring coffee','measuring a wall','carver 用于切烤肉。')]});
D('cascade',{etymology:e('cascade 经法语 cascade 来自意大利语 cascata、cascare“落下”，最初指陡落的小瀑布，后用于动词“倾泻”及事件连续发生的一连串。','cascade'),contexts:[c('cascade.s3','系统故障','One failed sensor triggered a cascade of errors across the control network, each fault causing the next until the operators shut the system down.','一个传感器失灵引发控制网络中一连串错误，每个故障又导致下一个，直到操作员关闭系统。','One failed sensor triggered a cascade of errors across the control network / each fault causing the next / until the operators shut the system down.','cascade 作 of errors 的中心名词；each fault causing the next 解释连续性。','故障接连触发后续故障，符合事件链义 s3。')],mistakes:[m('A cascade of failures occurred when one isolated problem happened and no other errors followed.','A single isolated failure occurred, with no further problems following it.','cascade 指接连发生的一串事件；只有一个故障且没有后续时不成立。')],quiz:[q('cascade',1,1,'A cascade of events is?','a series happening quickly one after another','one unrelated event after a long pause','a permanent stop to all activity','s3 指迅速连续发生的一连串事件。'),q('cascade',2,1,'A small steep waterfall is a?','cascade','carousel','carapace','名词 s1 可指小瀑布。'),q('cascade',3,2,'If water cascades down a slope, it?','falls rapidly like a waterfall','remains still in a sealed tank','flows upward into the sky','动词义 s2 是像瀑布一样倾泻而下。'),q('cascade',4,3,'One network fault triggering many others creates?','a cascade of failures','a single unrelated result','a carpel','连锁发生的错误是一连串事件。')]});
D('cascara',{etymology:e('cascara 在英语中借自西班牙语 cáscara“外皮、树皮”，常指药鼠李（cascara buckthorn）的树皮及其传统泻剂制品。','cascara'),contexts:[c('cascara.s1','药材史','The museum displayed a jar labeled cascara bark and noted that it had once been prepared as a strong laxative.','博物馆展示了一罐标为药鼠李树皮的样品，并说明它过去曾被制成强效泻剂。','The museum displayed a jar labeled cascara bark / and noted / that it had once been prepared as a strong laxative.','cascara 修饰 bark；that 从句说明其历史用途。','药鼠李树皮曾制为泻剂，符合词义。')],mistakes:[m('The apothecary labeled cascara as a sweet flower petal used only to decorate wedding cakes.','The apothecary labeled cascara as bark traditionally prepared as a laxative.','cascara 指药鼠李树皮，不是装饰用花瓣。')],quiz:[q('cascara',1,1,'Cascara refers to bark from which type of plant?','cascara buckthorn','a rose bush','a pine cone','cascara 是药鼠李树皮。'),q('cascara',2,1,'Historically, cascara bark was prepared as a?','laxative','sweetening syrup only','metal polish','它曾被用作泻剂。'),q('cascara',3,1,'The Spanish source cáscara means roughly?','peel or bark','heart','song','cascara 与西班牙语“外皮、树皮”相关。'),q('cascara',4,1,'A jar of cascara in an herb museum most likely contains?','buckthorn bark','fresh carnations','a small waterfall','药材语境中的 cascara 是树皮。')]});
D('cashmere',{etymology:e('cashmere 是 Kashmir（克什米尔）的历史英语拼写形式；因克什米尔地区以细软山羊绒织物闻名，词义发展为该绒毛及其织物。','cashmere'),contexts:[c('cashmere.s1','纺织品','The scarf was woven from cashmere, whose fine goat fibers made it warm without feeling heavy around the neck.','这条围巾由羊绒织成，细软的山羊纤维让它保暖，却不会压在脖子上显得沉重。','The scarf was woven from cashmere / whose fine goat fibers made it warm / without feeling heavy around the neck.','cashmere 作 from 的宾语；whose 从句说明纤维特性。','细软山羊绒及其制成的织物符合定义。')],mistakes:[m('The label claimed the sweater was cashmere, but it was made entirely from coarse plastic yarn and contained no goat fiber.','The label claimed the sweater was synthetic, because it was made entirely from coarse plastic yarn and contained no goat fiber.','完全由塑料纱线制成的衣服不是 cashmere 羊绒。')],quiz:[q('cashmere',1,1,'Cashmere fiber comes from?','fine hair of Kashmir goats','sheep wool only by definition','silkworm cocoons','cashmere 指细软山羊绒。'),q('cashmere',2,1,'A cashmere scarf is valued for being?','soft and warm','hard and brittle','made of metal wire','羊绒织物通常柔软保暖。'),q('cashmere',3,1,'Which garment could be made of cashmere?','a fine knit sweater','a steel helmet','a paper raincoat','羊绒可用于针织毛衣。'),q('cashmere',4,1,'The word cashmere is historically linked to?','Kashmir','Cambridge','Cardiff','词名与克什米尔地区相关。')]});
D('cast-iron',{etymology:e('cast-iron 是 cast 与 iron 构成的复合形容词，字面指把熔铁浇入模具制成；比喻义“极牢靠、无懈可击”由材料坚固特性发展而来。','cast-iron'),contexts:[c('cast-iron.s2','证据审查','The prosecutor lacked cast-iron evidence, so the judge dismissed the claim rather than treating the accusation as impossible to disprove.','检察官缺少铁证，因此法官驳回了指控，没有把它当作无法推翻的结论。','The prosecutor lacked cast-iron evidence / so the judge dismissed the claim / rather than treating the accusation as impossible to disprove.','cast-iron 修饰 evidence；so 引出缺乏铁证的结果。','这里比喻证据极为牢靠、难以推翻，对应 s2。')],mistakes:[m('She called the soft cotton pot cover cast-iron even though it contained no metal.','She called the soft cotton pot cover cotton because it contained no metal.','cast-iron 指铸铁材质；柔软且不含金属的棉质锅盖不能这样称呼。')],quiz:[q('cast-iron',1,1,'Cast-iron cookware is made from iron that has been?','cast in a mold','woven into cloth','carved from ice','字面义指把铁浇铸成型。'),q('cast-iron',2,2,'A cast-iron alibi means an alibi that is?','very strong and hard to disprove','made from an actual metal pot','obviously false and weak','比喻义指牢靠、难以推翻。'),q('cast-iron',3,1,'Which is a cast-iron object in the literal sense?','a heavy molded iron pan','a wool scarf','a wooden spoon','铸铁锅是字面义 cast-iron。'),q('cast-iron',4,2,'“Cast-iron evidence” means evidence that is?','conclusive and dependable','made of cookware','easy to disprove','该搭配表示确凿可靠的证据。')]});
D('caste',{etymology:e('caste 经法语 caste 来自葡萄牙语 casta“血统、类别”，最终源自拉丁语 castus“纯正的”；英语既指印度传统世袭阶层，也泛指排斥外人的僵化群体。','caste'),contexts:[c('caste.s2','社会结构','The historian used caste metaphorically for the closed professional group, whose members protected their privileges and rarely welcomed outsiders.','历史学家用 caste 比喻这个封闭的职业群体；成员维护自身特权，很少接纳外人。','The historian used caste metaphorically for the closed professional group / whose members protected their privileges / and rarely welcomed outsiders.','caste 作介词 for 的宾语；whose 从句描述群体特征。','封闭并排斥外人的僵化社会群体对应泛化义 s2。')],mistakes:[m('The society’s caste was a fully open club that welcomed every newcomer and treated all members identically.','The society’s club was fully open and welcomed every newcomer, unlike a rigid caste that excludes outsiders.','完全开放且欢迎新人，与 caste 的排他、僵化群体义相反。')],quiz:[q('caste',1,1,'A traditional caste is a?','hereditary social class','temporary weather condition','musical composition','caste s1 指世袭社会阶层。'),q('caste',2,2,'A metaphorical caste may be a group that?','keeps outsiders away and protects its status','invites everyone equally without barriers','changes membership every afternoon','s2 指排外、僵化的团体。'),q('caste',3,1,'Which word best contrasts with a rigid caste?','open community','hereditary class','closed social group','开放社群与排他的 caste 相反。'),q('caste',4,1,'The English word caste came through Portuguese from a word meaning?','lineage or class','small waterfall','yellow bird','葡萄牙语 casta 有血统、类别义。')]});

})();
